import {b,type ReviewedLesson} from './types';
type Pair=readonly [string,string];
const bi=([en,vi]:Pair)=>b(en,vi);
const q=(prompt:Pair,solution:Pair[])=>({prompt:bi(prompt),solution:solution.map(bi)});
const reviewed:Record<string,ReviewedLesson>={
  'f-w022-e1':{
    application:bi(['A reliability team can bound how often an IID sample average misses its population mean without knowing the full distribution.','Nhóm độ tin cậy có thể chặn xác suất trung bình mẫu IID lệch khỏi trung bình tổng thể mà không cần biết toàn bộ phân phối.']),
    formula:bi(['For IID variables with finite variance $\\sigma^2$, $\\operatorname{Var}(\\bar X_n)=\\sigma^2/n$ and $\\Pr(|\\bar X_n-\\mu|\\ge\\varepsilon)\\le\\sigma^2/(n\\varepsilon^2)$ for $\\varepsilon>0$.','Với biến IID có phương sai hữu hạn $\\sigma^2$, $\\operatorname{Var}(\\bar X_n)=\\sigma^2/n$ và $\\Pr(|\\bar X_n-\\mu|\\ge\\varepsilon)\\le\\sigma^2/(n\\varepsilon^2)$ với $\\varepsilon>0$.']),
    steps:[bi(['Center the sample average at its expectation $\\mu$.','Đưa trung bình mẫu về quanh kỳ vọng $\\mu$.' ]),bi(['Use independence to make the variance of the average equal $\\sigma^2/n$.','Dùng độc lập để phương sai trung bình bằng $\\sigma^2/n$.' ]),bi(['Apply Chebyshev to the centered average; the bound tends to zero for fixed $\\varepsilon>0$.','Áp dụng Chebyshev cho trung bình đã tâm; chặn tiến về không với $\\varepsilon>0$ cố định.' ])],
    primarySolution:[bi(['Linearity gives $E\\bar X_n=\\mu$; independence gives $\\operatorname{Var}(\\bar X_n)=n\\sigma^2/n^2=\\sigma^2/n$.','Tính tuyến tính cho $E\\bar X_n=\\mu$; độc lập cho $\\operatorname{Var}(\\bar X_n)=n\\sigma^2/n^2=\\sigma^2/n$.' ]),bi(['Chebyshev at threshold $\\varepsilon$ yields $\\Pr(|\\bar X_n-\\mu|\\ge\\varepsilon)\\le(\\sigma^2/n)/\\varepsilon^2=\\sigma^2/(n\\varepsilon^2)$.','Chebyshev tại ngưỡng $\\varepsilon$ cho $\\Pr(|\\bar X_n-\\mu|\\ge\\varepsilon)\\le(\\sigma^2/n)/\\varepsilon^2=\\sigma^2/(n\\varepsilon^2)$.' ]),bi(['For fixed $\\varepsilon>0$ and finite $\\sigma^2$, this bound tends to zero, proving convergence in probability.','Với $\\varepsilon>0$ cố định và $\\sigma^2$ hữu hạn, chặn tiến về không, chứng minh hội tụ theo xác suất.' ])],
    companions:[
      q(['IID observations have variance $9$. How large must $n$ be so Chebyshev bounds $\\Pr(|\\bar X_n-\\mu|\\ge0.5)$ by at most $0.1$?','Quan sát IID có phương sai $9$. Cần $n$ ít nhất bao nhiêu để Chebyshev chặn $\\Pr(|\\bar X_n-\\mu|\\ge0.5)$ không quá $0.1$?'],[['Set $9/(n(0.5)^2)\\le0.1$; the denominator threshold is $0.25n$.','Đặt $9/(n(0.5)^2)\\le0.1$; mẫu số là $0.25n$.' ],['Thus $36/n\\le0.1$, so $n\\ge360$.','Suy ra $36/n\\le0.1$, nên $n\\ge360$.' ],['This is a sufficient sample size for the bound, not a necessary size for the actual probability.','Đây là cỡ mẫu đủ cho chặn, không nhất thiết cần cho xác suất thật.' ]]),
      q(['For IID data with variance $4$, prove that $\\bar X_n$ converges in probability to $\\mu$ using only the displayed bound.','Với dữ liệu IID có phương sai $4$, chứng minh $\\bar X_n$ hội tụ theo xác suất về $\\mu$ chỉ bằng chặn đã nêu.'],[['Fix any $\\varepsilon>0$ and write the bound as $\\Pr(|\\bar X_n-\\mu|\\ge\\varepsilon)\\le4/(n\\varepsilon^2)$.','Chọn $\\varepsilon>0$ bất kỳ và viết chặn $\\Pr(|\\bar X_n-\\mu|\\ge\\varepsilon)\\le4/(n\\varepsilon^2)$.' ],['With this fixed $\\varepsilon$, the right side tends to zero as $n\\to\\infty$.','Với $\\varepsilon$ cố định, vế phải tiến về không khi $n\\to\\infty$.' ],['That is exactly the definition of convergence in probability.','Đó chính là định nghĩa hội tụ theo xác suất.' ]]),
      q(['Let $X_i$ be IID with mean $2$ and variance $1$. Find a Chebyshev upper bound for $\\Pr(|\\bar X_{25}-2|\\ge0.4)$.','Cho $X_i$ IID có trung bình $2$ và phương sai $1$. Tìm chặn trên Chebyshev cho $\\Pr(|\\bar X_{25}-2|\\ge0.4)$.'],[['The average variance is $1/25$.','Phương sai trung bình là $1/25$.' ],['Chebyshev gives $(1/25)/(0.4)^2=(1/25)/0.16=0.25$.','Chebyshev cho $(1/25)/(0.4)^2=(1/25)/0.16=0.25$.' ],['So the probability is at most $0.25$; the inequality need not be sharp.','Vậy xác suất không quá $0.25$; bất đẳng thức không nhất thiết chặt.' ]])
    ],
    reviewNote:'Checked the proof uses IID finite-variance data, fixed ε>0, and Chebyshev; the sample-size calculation is a sufficient bound.',
    sourceIds:['f-6041sc']
  },
  'f-w022-e2':{
    application:bi(['A normal approximation estimates a binomial tail when the count is large; shifting a discrete cutoff by half a unit aligns the event boundary.','Xấp xỉ chuẩn ước lượng đuôi nhị thức khi số đếm lớn; dịch ngưỡng rời rạc nửa đơn vị để căn chỉnh biên biến cố.']),
    formula:bi(['For $S\\sim\\operatorname{Binomial}(n,p)$, use $\\mu=np$, $\\sigma=\\sqrt{np(1-p)}$; approximate $\\Pr(S\\ge k)$ by $1-\\Phi((k-0.5-\\mu)/\\sigma)$.','Với $S\\sim\\operatorname{Binomial}(n,p)$, dùng $\\mu=np$, $\\sigma=\\sqrt{np(1-p)}$; xấp xỉ $\\Pr(S\\ge k)$ bằng $1-\\Phi((k-0.5-\\mu)/\\sigma)$.']),
    steps:[bi(['Compute the binomial mean and variance from $n,p$.','Tính kỳ vọng và phương sai nhị thức từ $n,p$.' ]),bi(['For an upper tail starting at integer $k$, replace the cutoff by $k-0.5$.','Với đuôi trên bắt đầu ở số nguyên $k$, thay ngưỡng bằng $k-0.5$.' ]),bi(['Standardize the corrected boundary and evaluate a normal tail; label the result approximate.','Chuẩn hóa biên đã hiệu chỉnh và tính đuôi chuẩn; ghi rõ kết quả là xấp xỉ.' ])],
    primarySolution:[bi(['For $n=100,p=0.3$, $E S=30$ and $\\operatorname{Var}(S)=100(0.3)(0.7)=21$, so $\\sigma=\\sqrt{21}$.','Với $n=100,p=0.3$, $E S=30$ và $\\operatorname{Var}(S)=100(0.3)(0.7)=21$, nên $\\sigma=\\sqrt{21}$.' ]),bi(['The event $S\\ge35$ has corrected normal cutoff $34.5$; $z=(34.5-30)/\\sqrt{21}\\approx0.982$.','Biến cố $S\\ge35$ có ngưỡng chuẩn hiệu chỉnh $34.5$; $z=(34.5-30)/\\sqrt{21}\\approx0.982$.' ]),bi(['Therefore the approximation is $1-\\Phi(0.982)\\approx0.163$ (about $0.164$ with coarser rounding), not an exact binomial probability.','Vậy xấp xỉ là $1-\\Phi(0.982)\\approx0.163$ (khoảng $0.164$ nếu làm tròn thô), không phải xác suất nhị thức chính xác.' ])],
    companions:[
      q(['For $S\\sim\\operatorname{Binomial}(80,0.25)$, approximate $\\Pr(S\\ge25)$ with continuity correction.','Với $S\\sim\\operatorname{Binomial}(80,0.25)$, xấp xỉ $\\Pr(S\\ge25)$ bằng hiệu chỉnh liên tục.'],[['The mean is $20$ and variance is $80(0.25)(0.75)=15$, so $\\sigma=\\sqrt{15}$.','Kỳ vọng là $20$, phương sai $80(0.25)(0.75)=15$, nên $\\sigma=\\sqrt{15}$.' ],['Correct the lower count boundary to $24.5$; then $z=(24.5-20)/\\sqrt{15}\\approx1.162$.','Hiệu chỉnh cận dưới thành $24.5$; khi đó $z=(24.5-20)/\\sqrt{15}\\approx1.162$.' ],['The upper-tail approximation is $1-\\Phi(1.162)\\approx0.123$.','Xác suất đuôi trên xấp xỉ $1-\\Phi(1.162)\\approx0.123$.' ]]),
      q(['For $S\\sim\\operatorname{Binomial}(200,0.5)$, approximate $\\Pr(S\\le90)$ with a continuity correction.','Với $S\\sim\\operatorname{Binomial}(200,0.5)$, xấp xỉ $\\Pr(S\\le90)$ bằng hiệu chỉnh liên tục.'],[['Here $\\mu=100$ and $\\sigma=\\sqrt{50}$.','Ở đây $\\mu=100$ và $\\sigma=\\sqrt{50}$.' ],['The inclusive upper count 90 becomes 90.5, so $z=(90.5-100)/\\sqrt{50}\\approx-1.344$.','Số đếm trên bao gồm 90 thành 90.5, nên $z=(90.5-100)/\\sqrt{50}\\approx-1.344$.' ],['Thus the lower-tail approximation is $\\Phi(-1.344)\\approx0.0895$.','Vậy xấp xỉ đuôi dưới là $\\Phi(-1.344)\\approx0.0895$.' ]]),
      q(['For $S\\sim\\operatorname{Binomial}(50,0.2)$, approximate $\\Pr(S=12)$ by a normal interval correction.','Với $S\\sim\\operatorname{Binomial}(50,0.2)$, xấp xỉ $\\Pr(S=12)$ bằng hiệu chỉnh khoảng chuẩn.'],[['The mean is $10$ and variance is $8$, giving $\\sigma=\\sqrt8$.','Kỳ vọng là $10$, phương sai là $8$, nên $\\sigma=\\sqrt8$.' ],['The single count is represented by $11.5<Y<12.5$; the endpoint z-scores are $1.5/\\sqrt8$ and $2.5/\\sqrt8$.','Số đếm đơn được biểu diễn bởi $11.5<Y<12.5$; các z-score hai đầu là $1.5/\\sqrt8$ và $2.5/\\sqrt8$.' ],['The approximation is $\\Phi(2.5/\\sqrt8)-\\Phi(1.5/\\sqrt8)\\approx0.095$.','Xấp xỉ là $\\Phi(2.5/\\sqrt8)-\\Phi(1.5/\\sqrt8)\\approx0.095$.' ]])
    ],
    reviewNote:'Checked mean, variance, upper/lower inclusive half-unit shifts and the distinction between a normal approximation and the exact binomial tail.',
    sourceIds:['f-6041sc']
  },
  'f-w022-e3':{
    application:bi(['Repeated measurements of one shared environmental shock are correlated; their average does not gain precision at the independent-sample rate.','Các phép đo lặp cùng chịu một cú sốc môi trường sẽ tương quan; trung bình không tăng độ chính xác theo tốc độ mẫu độc lập.']),
    formula:bi(['For any finite-variance variables, $\\operatorname{Var}(\\bar X_n)=n^{-2}\\sum_{i,j}\\operatorname{Cov}(X_i,X_j)$; IID scaling $\\sigma^2/n$ needs zero cross-covariances.','Với biến có phương sai hữu hạn, $\\operatorname{Var}(\\bar X_n)=n^{-2}\\sum_{i,j}\\operatorname{Cov}(X_i,X_j)$; tốc độ IID $\\sigma^2/n$ cần hiệp phương sai chéo bằng không.']),
    steps:[bi(['Expand the variance of the sum, retaining every covariance term.','Khai triển phương sai tổng, giữ lại mọi số hạng hiệp phương sai.' ]),bi(['Under independence, cross-covariances vanish; under shared dependence, they remain.','Khi độc lập, hiệp phương sai chéo mất đi; khi cùng phụ thuộc, chúng còn lại.' ]),bi(['Compare the actual covariance sum to the IID formula before claiming variance reduction.','So sánh tổng hiệp phương sai thực với công thức IID trước khi kết luận phương sai giảm.' ])],
    primarySolution:[bi(['If $X_i=Z$ for all $i$, then $\\bar X_n=n^{-1}(nZ)=Z$.','Nếu $X_i=Z$ với mọi $i$, thì $\\bar X_n=n^{-1}(nZ)=Z$.' ]),bi(['Since $\\operatorname{Var}(Z)=1$, the average has variance $1$, not $1/n$.','Vì $\\operatorname{Var}(Z)=1$, trung bình có phương sai $1$, không phải $1/n$.' ]),bi(['The IID rule fails because each pair has covariance $1$; averaging identical copies removes no noise.','Quy tắc IID sai vì mọi cặp có hiệp phương sai $1$; lấy trung bình các bản sao giống hệt không loại bỏ nhiễu.' ])],
    companions:[
      q(['Suppose $\\operatorname{Var}(X_i)=4$ and $\\operatorname{Cov}(X_i,X_j)=1$ for every $i\\ne j$. Find $\\operatorname{Var}(\\bar X_3)$.','Giả sử $\\operatorname{Var}(X_i)=4$ và $\\operatorname{Cov}(X_i,X_j)=1$ với mọi $i\\ne j$. Tính $\\operatorname{Var}(\\bar X_3)$.'],[['The variance of the sum has three diagonal terms and six ordered off-diagonal terms: $3(4)+6(1)=18$.','Phương sai tổng có ba số hạng đường chéo và sáu số hạng ngoài đường chéo có thứ tự: $3(4)+6(1)=18$.' ],['Divide by $3^2$ to get $\\operatorname{Var}(\\bar X_3)=18/9=2$.','Chia cho $3^2$ được $\\operatorname{Var}(\\bar X_3)=18/9=2$.' ],['The independent calculation would be $4/3$, so positive covariance makes the mean less precise.','Nếu độc lập thì kết quả là $4/3$; hiệp phương sai dương làm trung bình kém chính xác hơn.' ]]),
      q(['Let $X_i=Z+\\epsilon_i$, where $\\operatorname{Var}(Z)=2$, the independent errors have variance $3$, and all errors are independent of $Z$. Find $\\operatorname{Var}(\\bar X_n)$.','Cho $X_i=Z+\\epsilon_i$, với $\\operatorname{Var}(Z)=2$, các sai số độc lập có phương sai $3$, và mọi sai số độc lập với $Z$. Tính $\\operatorname{Var}(\\bar X_n)$.'],[['Average the decomposition: $\\bar X_n=Z+\\bar\\epsilon_n$.','Lấy trung bình phân rã: $\\bar X_n=Z+\\bar\\epsilon_n$.' ],['Independence makes the variance $2+3/n$.','Độc lập cho phương sai $2+3/n$.' ],['As $n$ grows the idiosyncratic error shrinks, but the common shock leaves variance $2$.','Khi $n$ tăng, sai số riêng giảm nhưng cú sốc chung vẫn để lại phương sai $2$.' ]]),
      q(['A stationary sequence has variance $5$ and lag-one covariance $-1$. Find the variance of its two-term average.','Một chuỗi dừng có phương sai $5$ và hiệp phương sai trễ một là $-1$. Tính phương sai trung bình hai số hạng.'],[['Use $\\operatorname{Var}(X_1+X_2)=5+5+2(-1)=8$.','Dùng $\\operatorname{Var}(X_1+X_2)=5+5+2(-1)=8$.' ],['Scaling the sum by $1/2$ squares the factor, so variance is $8/4=2$.','Nhân tổng với $1/2$ làm bình phương hệ số, nên phương sai là $8/4=2$.' ],['The IID value would be $5/2$; negative covariance explains the smaller actual variance.','Giá trị IID là $5/2$; hiệp phương sai âm giải thích phương sai thật nhỏ hơn.' ]])
    ],
    reviewNote:'Checked the covariance expansion and each example; the perfectly shared variable has variance one for every sample size.',
    sourceIds:['f-6041sc']
  },
  'f-w022-e4':{
    application:bi(['When reporting uncertainty of an estimated average, the standard error describes estimator-to-estimator variation, while the population standard deviation describes individual observations.','Khi báo bất định của trung bình ước lượng, sai số chuẩn mô tả biến thiên giữa các ước lượng, còn độ lệch chuẩn tổng thể mô tả các quan sát cá nhân.']),
    formula:bi(['For IID observations with standard deviation $\\sigma$ and finite variance, $\\operatorname{SD}(\\bar X_n)=\\sigma/\\sqrt n$; independence is needed for this scaling.','Với quan sát IID có độ lệch chuẩn $\\sigma$ và phương sai hữu hạn, $\\operatorname{SD}(\\bar X_n)=\\sigma/\\sqrt n$; cần độc lập để có tỷ lệ này.']),
    steps:[bi(['Start from $\\operatorname{Var}(X_i)=\\sigma^2$.','Bắt đầu từ $\\operatorname{Var}(X_i)=\\sigma^2$.' ]),bi(['Add independent variances and divide by $n^2$ for the average.','Cộng phương sai độc lập rồi chia cho $n^2$ cho trung bình.' ]),bi(['Take the square root; distinguish this estimator spread from individual spread $\\sigma$.','Lấy căn; phân biệt độ phân tán ước lượng với độ phân tán cá nhân $\\sigma$.' ])],
    primarySolution:[bi(['The variance of the average is $\\sigma^2/n$ under IID sampling.','Phương sai trung bình là $\\sigma^2/n$ khi lấy mẫu IID.' ]),bi(['Thus $\\operatorname{SD}(\\bar X)=\\sigma/\\sqrt n=6/\\sqrt{36}=1$.','Vậy $\\operatorname{SD}(\\bar X)=\\sigma/\\sqrt n=6/\\sqrt{36}=1$.' ]),bi(['A single observation still has SD $6$; the smaller SD $1$ applies to the sample mean.','Một quan sát vẫn có SD $6$; SD nhỏ hơn bằng $1$ áp dụng cho trung bình mẫu.' ])],
    companions:[
      q(['Independent measurements have population SD $10$. Find the sample size needed for the mean to have standard error $2$.','Các phép đo độc lập có SD tổng thể $10$. Cần cỡ mẫu bao nhiêu để trung bình có sai số chuẩn $2$?'],[['Set $10/\\sqrt n=2$.','Đặt $10/\\sqrt n=2$.' ],['Then $\\sqrt n=5$, so $n=25$.','Suy ra $\\sqrt n=5$, nên $n=25$.' ],['The result uses independence and a finite variance; dependence may change the standard error.','Kết quả dùng giả thiết độc lập và phương sai hữu hạn; phụ thuộc có thể làm sai số chuẩn khác đi.' ]]),
      q(['If $\\sigma=8$ and $n=16$, compare the SD of one observation with the SE of the sample mean.','Nếu $\\sigma=8$ và $n=16$, so sánh SD của một quan sát với SE của trung bình mẫu.'],[['Individual spread is $8$.','Độ phân tán cá nhân là $8$.' ],['The mean SE is $8/\\sqrt{16}=2$.','SE của trung bình là $8/\\sqrt{16}=2$.' ],['The averaging reduces standard deviation by factor $\\sqrt{16}=4$, not by factor $16$.','Lấy trung bình giảm độ lệch chuẩn theo hệ số $\\sqrt{16}=4$, không phải $16$.' ]]),
      q(['Four IID observations have variance $9$. Find the variance and standard error of their average.','Bốn quan sát IID có phương sai $9$. Tìm phương sai và sai số chuẩn của trung bình.'],[['The average variance is $9/4=2.25$.','Phương sai trung bình là $9/4=2.25$.' ],['Its standard error is $\\sqrt{2.25}=1.5$.','Sai số chuẩn là $\\sqrt{2.25}=1.5$.' ],['The original observation SD is $3$, confirming that the mean is less variable.','SD quan sát gốc là $3$, xác nhận trung bình biến thiên ít hơn.' ]])
    ],
    reviewNote:'Checked the IID finite-variance condition, square-root scaling, and distinction between observation SD and estimator SE.',
    sourceIds:['f-6041sc']
  },
  'f-w022-e5':{
    application:bi(['A large sample alone does not authorize a central limit approximation: the sampling assumptions and a nonzero finite variance determine which theorem applies.','Chỉ mẫu lớn không đủ để dùng xấp xỉ giới hạn trung tâm: giả thiết lấy mẫu và phương sai hữu hạn khác không quyết định định lý áp dụng.']),
    formula:bi(['The classical IID CLT assumes independent identically distributed $X_i$ with $0<\\sigma^2<\\infty$ and states $\\sqrt n(\\bar X_n-\\mu)/\\sigma\\Rightarrow N(0,1)$.','CLT IID cổ điển giả sử $X_i$ độc lập cùng phân phối và $0<\\sigma^2<\\infty$, kết luận $\\sqrt n(\\bar X_n-\\mu)/\\sigma\\Rightarrow N(0,1)$.']),
    steps:[bi(['Identify whether observations are IID and whether the variance is finite and positive.','Xác định quan sát có IID không và phương sai có hữu hạn, dương không.' ]),bi(['Check that the statistic uses the CLT normalization $\\sqrt n$ and true $\\sigma$.','Kiểm tra thống kê dùng chuẩn hóa CLT $\\sqrt n$ và $\\sigma$ thật.' ]),bi(['If a hypothesis fails, do not invoke this classical version; seek a theorem with matching conditions.','Nếu giả thiết sai, không viện dẫn dạng cổ điển này; tìm định lý có điều kiện phù hợp.' ])],
    primarySolution:[bi(['The stated classical CLT requires IID observations with finite mean $\\mu$ and $0<\\sigma^2<\\infty$.','CLT cổ điển yêu cầu quan sát IID có kỳ vọng hữu hạn $\\mu$ và $0<\\sigma^2<\\infty$.' ]),bi(['Its statistic is $\\sqrt n(\\bar X_n-\\mu)/\\sigma$, which converges in distribution to $N(0,1)$.','Thống kê là $\\sqrt n(\\bar X_n-\\mu)/\\sigma$, hội tụ theo phân phối đến $N(0,1)$.' ]),bi(['Because the setting here fails an IID/nonzero-finite-variance hypothesis, this theorem cannot be used as stated; this does not rule out another applicable limit theorem.','Vì bối cảnh này vi phạm giả thiết IID/phương sai hữu hạn khác không, không thể dùng nguyên dạng định lý này; điều đó không loại trừ định lý giới hạn khác phù hợp.' ])],
    companions:[
      q(['Let $X_i=Z$ for every $i$, with $Z$ a Rademacher variable taking $-1$ and $1$ equally. Why does the classical IID CLT not apply to these observations?','Cho $X_i=Z$ với mọi $i$, trong đó $Z$ nhận $-1$ và $1$ đồng xác suất. Vì sao CLT IID cổ điển không áp dụng cho các quan sát này?'],[['Each variable has mean $0$ and variance $1$, so the marginal moment conditions hold.','Mỗi biến có trung bình $0$, phương sai $1$, nên điều kiện moment biên thỏa.' ],['However, all observations are identical, so for $i\\ne j$, $\\operatorname{Cov}(X_i,X_j)=1$ and independence fails.','Tuy nhiên mọi quan sát giống hệt, nên với $i\\ne j$, $\\operatorname{Cov}(X_i,X_j)=1$ và độc lập sai.' ],['The classical IID CLT therefore cannot be invoked; the normalized sum equals $\\sqrt n Z$, not a standard-normal limit.','Vì vậy không thể viện dẫn CLT IID cổ điển; tổng chuẩn hóa bằng $\\sqrt n Z$, không có giới hạn chuẩn tắc.' ]]),
      q(['A sample consists of IID variables with variance $0$. Explain what the classical CLT normalization does and why its standard statement is inapplicable.','Mẫu gồm biến IID có phương sai $0$. Giải thích chuẩn hóa CLT làm gì và vì sao phát biểu chuẩn không áp dụng.'],[['Variance zero means each variable equals its mean almost surely.','Phương sai không nghĩa là mỗi biến bằng kỳ vọng hầu chắc chắn.' ],['The denominator $\\sigma$ in $\\sqrt n(\\bar X_n-\\mu)/\\sigma$ is zero, so the displayed normalization is undefined.','Mẫu số $\\sigma$ trong $\\sqrt n(\\bar X_n-\\mu)/\\sigma$ bằng không, nên chuẩn hóa đó không xác định.' ],['The positive-variance hypothesis fails; the degenerate constant sequence has no nondegenerate $N(0,1)$ limit under that formula.','Giả thiết phương sai dương sai; dãy hằng suy biến không có giới hạn $N(0,1)$ không suy biến theo công thức đó.' ]]),
      q(['Suppose independent, non-identically distributed variables have finite variances. Is the IID CLT automatically justified? State the needed reasoning.','Giả sử các biến độc lập, không cùng phân phối có phương sai hữu hạn. CLT IID có tự động được biện minh không? Nêu lập luận cần thiết.'],[['No: the hypotheses “identically distributed” are not met, even though independence and finite variances hold.','Không: giả thiết “cùng phân phối” không thỏa dù có độc lập và phương sai hữu hạn.' ],['A different result, such as a suitable triangular-array CLT, would need its own conditions (for example a Lindeberg-type condition).','Một kết quả khác như CLT mảng tam giác phù hợp cần điều kiện riêng (chẳng hạn điều kiện kiểu Lindeberg).' ],['One must verify that theorem’s assumptions rather than infer normality merely from large $n$.','Phải kiểm tra giả thiết định lý đó thay vì suy ra chuẩn chỉ từ $n$ lớn.' ]])
    ],
    reviewNote:'Checked that the classical CLT requires IID, finite mean, and strictly positive finite variance; rejection of this theorem is not a claim that no other CLT applies.',
    sourceIds:['f-6041sc']
  },
  'f-w023-e1':{
    application:bi(['A two-state customer or machine model has long-run state frequencies obtained by solving its stationary balance equations.','Mô hình khách hàng hoặc máy hai trạng thái có tần suất trạng thái dài hạn tìm bằng cách giải phương trình cân bằng dừng.']),
    formula:bi(['For $P=\\begin{pmatrix}a&1-a\\\\b&1-b\\end{pmatrix}$ with $a,b\\in[0,1]$, solve $\\pi P=\\pi$, $\\pi_1+\\pi_2=1$; when $a+b>0$, $\\pi_1=b/(b+1-a)$.','Với $P=\\begin{pmatrix}a&1-a\\\\b&1-b\\end{pmatrix}$, $a,b\\in[0,1]$, giải $\\pi P=\\pi$, $\\pi_1+\\pi_2=1$; khi $a+b>0$, $\\pi_1=b/(b+1-a)$.']),
    steps:[bi(['Write one stationary equation and the normalization; the second balance equation is redundant.','Viết một phương trình dừng và điều kiện chuẩn hóa; phương trình cân bằng còn lại phụ thuộc.' ]),bi(['Substitute the transition probabilities and isolate one component of $\\pi$.','Thay xác suất chuyển và giải một thành phần của $\\pi$.' ]),bi(['Check nonnegativity, unit sum, and direct multiplication $\\pi P=\\pi$.','Kiểm tra không âm, tổng bằng một và nhân trực tiếp $\\pi P=\\pi$.' ])],
    primarySolution:[bi(['Let $\\pi=(u,1-u)$. The first-coordinate equation is $u=0.9u+0.2(1-u)$.','Đặt $\\pi=(u,1-u)$. Phương trình tọa độ thứ nhất là $u=0.9u+0.2(1-u)$.' ]),bi(['Thus $0.3u=0.2$, so $u=2/3$ and $1-u=1/3$.','Suy ra $0.3u=0.2$, nên $u=2/3$ và $1-u=1/3$.' ]),bi(['Check: $(2/3,1/3)P=(0.6+0.066\\overline6,0.066\\overline6+0.266\\overline6)=(2/3,1/3)$.','Kiểm tra: $(2/3,1/3)P=(0.6+0.066\\overline6,0.066\\overline6+0.266\\overline6)=(2/3,1/3)$.' ]),bi(['Both transitions between the two states are positive, so the chain is irreducible; the positive self-loops make it aperiodic.','Hai chiều chuyển giữa hai trạng thái đều có xác suất dương nên chuỗi bất khả quy; xác suất tự lặp dương làm chuỗi phi tuần hoàn.' ])],
    companions:[
      q(['Find the stationary distribution of $P=\\begin{pmatrix}0.7&0.3\\\\0.1&0.9\\end{pmatrix}$ and check it.','Tìm phân phối dừng của $P=\\begin{pmatrix}0.7&0.3\\\\0.1&0.9\\end{pmatrix}$ và kiểm tra.'],[['Write $\\pi=(u,1-u)$ and solve $u=0.7u+0.1(1-u)$.','Viết $\\pi=(u,1-u)$ rồi giải $u=0.7u+0.1(1-u)$.' ],['This gives $0.4u=0.1$, hence $u=1/4$ and $\\pi=(1/4,3/4)$.','Suy ra $0.4u=0.1$, nên $u=1/4$ và $\\pi=(1/4,3/4)$.' ],['Multiplication returns $(0.175+0.075,0.075+0.675)=(1/4,3/4)$.','Nhân ma trận cho $(0.175+0.075,0.075+0.675)=(1/4,3/4)$.' ]]),
      q(['For $P=\\begin{pmatrix}0.8&0.2\\\\0.4&0.6\\end{pmatrix}$, compute the stationary probability of state 1 and its long-run expected count in 50 stationary steps.','Với $P=\\begin{pmatrix}0.8&0.2\\\\0.4&0.6\\end{pmatrix}$, tính xác suất dừng của trạng thái 1 và số lần kỳ vọng dài hạn trong 50 bước dừng.'],[['The balance equation is $0.2\\pi_1=0.4\\pi_2$, so $\\pi_1=2\\pi_2$.','Phương trình cân bằng là $0.2\\pi_1=0.4\\pi_2$, nên $\\pi_1=2\\pi_2$.' ],['Normalization yields $\\pi_1=2/3$ and $\\pi_2=1/3$.','Chuẩn hóa cho $\\pi_1=2/3$ và $\\pi_2=1/3$.' ],['If the chain starts stationary, expected visits over 50 indexed times equal $50(2/3)=100/3$; stationarity justifies each marginal probability.','Nếu chuỗi khởi đầu dừng, số lần ghé kỳ vọng qua 50 thời điểm bằng $50(2/3)=100/3$; tính dừng bảo đảm mỗi xác suất biên như vậy.' ]]),
      q(['Consider $P=\\begin{pmatrix}1&0\\\\0.3&0.7\\end{pmatrix}$. Find all stationary distributions and explain the role of reducibility.','Xét $P=\\begin{pmatrix}1&0\\\\0.3&0.7\\end{pmatrix}$. Tìm mọi phân phối dừng và giải thích vai trò tính khả quy.'],[['State 1 is absorbing, so $\\delta_1=(1,0)$ is stationary.','Trạng thái 1 hấp thụ, nên $\\delta_1=(1,0)$ là dừng.' ],['If $\\pi=(u,1-u)$, stationarity in coordinate 2 requires $1-u=0.7(1-u)$, forcing $u=1$.','Nếu $\\pi=(u,1-u)$, tính dừng ở tọa độ 2 đòi $1-u=0.7(1-u)$, buộc $u=1$.' ],['Thus it is the only stationary distribution. The chain is reducible, so the general finite irreducible-chain uniqueness theorem does not supply the conclusion here; it follows by direct algebra.','Vậy đây là phân phối dừng duy nhất. Chuỗi khả quy nên định lý duy nhất tổng quát cho chuỗi hữu hạn bất khả quy không áp dụng; kết quả theo đại số trực tiếp.' ]])
    ],
    reviewNote:'Solved the row-stochastic stationary equations directly; irreducibility and aperiodicity are checked separately and are not needed merely to verify πP=π.',
    sourceIds:['f-6041sc']
  },
  'f-w023-e2':{
    application:bi(['In reversible random walks, local flow balance is easier to verify than multiplying a full stationary vector through every transition.','Trong bước đi ngẫu nhiên thuận nghịch, cân bằng dòng cục bộ dễ kiểm hơn nhân toàn bộ vectơ dừng với ma trận chuyển.']),
    formula:bi(['If $P$ is row-stochastic and $\\pi_iP_{ij}=\\pi_jP_{ji}$ for every pair, then $\\pi P=\\pi$; detailed balance is sufficient, not necessary.','Nếu $P$ stochastic theo hàng và $\\pi_iP_{ij}=\\pi_jP_{ji}$ với mọi cặp, thì $\\pi P=\\pi$; cân bằng chi tiết là điều kiện đủ, không phải điều kiện cần.']),
    steps:[bi(['For a fixed destination $j$, sum the detailed-balance identity over all source states $i$.','Với đích $j$ cố định, cộng đẳng thức cân bằng chi tiết theo mọi trạng thái nguồn $i$.' ]),bi(['Factor out $\\pi_j$ and use that row $j$ of $P$ sums to one.','Đưa $\\pi_j$ ra ngoài và dùng tổng hàng $j$ của $P$ bằng một.' ]),bi(['Conclude invariance; do not infer that every invariant chain must be reversible.','Kết luận bất biến; không suy ra mọi chuỗi bất biến đều thuận nghịch.' ])],
    primarySolution:[bi(['For each $j$, $(\\pi P)_j=\\sum_i\\pi_iP_{ij}$.','Với mỗi $j$, $(\\pi P)_j=\\sum_i\\pi_iP_{ij}$.' ]),bi(['Detailed balance changes this to $\\sum_i\\pi_jP_{ji}=\\pi_j\\sum_iP_{ji}$.','Cân bằng chi tiết đổi tổng thành $\\sum_i\\pi_jP_{ji}=\\pi_j\\sum_iP_{ji}$.' ]),bi(['Since row $j$ sums to one, $(\\pi P)_j=\\pi_j$. This holds for every $j$, hence $\\pi P=\\pi$.','Vì hàng $j$ có tổng bằng một, $(\\pi P)_j=\\pi_j$. Đúng với mọi $j$, nên $\\pi P=\\pi$.' ])],
    companions:[
      q(['Verify detailed balance for $\\pi=(1/3,2/3)$ and $P=\\begin{pmatrix}0.8&0.2\\\\0.1&0.9\\end{pmatrix}$, then state stationarity.','Kiểm tra cân bằng chi tiết với $\\pi=(1/3,2/3)$ và $P=\\begin{pmatrix}0.8&0.2\\\\0.1&0.9\\end{pmatrix}$, rồi kết luận tính dừng.'],[['The only nontrivial pair satisfies $\\pi_1P_{12}=(1/3)(0.2)=1/15$.','Cặp khác đường chéo thỏa $\\pi_1P_{12}=(1/3)(0.2)=1/15$.' ],['The reverse flow is $\\pi_2P_{21}=(2/3)(0.1)=1/15$; diagonal equations are automatic.','Dòng ngược là $\\pi_2P_{21}=(2/3)(0.1)=1/15$; phương trình đường chéo tự đúng.' ],['Thus detailed balance holds, and the summation argument proves $\\pi P=\\pi$.','Vậy cân bằng chi tiết đúng, và lập luận tổng chứng minh $\\pi P=\\pi$.' ]]),
      q(['For a symmetric row-stochastic matrix $P=\\begin{pmatrix}0.6&0.4\\\\0.4&0.6\\end{pmatrix}$, use detailed balance to find a stationary distribution.','Với ma trận đối xứng stochastic theo hàng $P=\\begin{pmatrix}0.6&0.4\\\\0.4&0.6\\end{pmatrix}$, dùng cân bằng chi tiết tìm phân phối dừng.'],[['Try uniform weights $\\pi=(1/2,1/2)$.','Thử trọng số đều $\\pi=(1/2,1/2)$.' ],['For the off-diagonal pair both flows equal $(1/2)(0.4)=0.2$; diagonal pairs match themselves.','Với cặp ngoài đường chéo, hai dòng đều $(1/2)(0.4)=0.2$; cặp đường chéo tự bằng nhau.' ],['Detailed balance holds, so $\\pi$ is stationary.','Cân bằng chi tiết đúng nên $\\pi$ là dừng.' ]]),
      q(['Show that $P=\\begin{pmatrix}0&1&0\\\\0&0&1\\\\1&0&0\\end{pmatrix}$ with uniform $\\pi$ is stationary but not reversible.','Chứng minh $P=\\begin{pmatrix}0&1&0\\\\0&0&1\\\\1&0&0\\end{pmatrix}$ với $\\pi$ đều là dừng nhưng không thuận nghịch.'],[['Each column also sums to one, so the uniform row vector satisfies $\\pi P=\\pi$.','Mỗi cột cũng có tổng một, nên vectơ hàng đều thỏa $\\pi P=\\pi$.' ],['For states 1 and 2, $\\pi_1P_{12}=1/3$ but $\\pi_2P_{21}=0$.','Với trạng thái 1 và 2, $\\pi_1P_{12}=1/3$ nhưng $\\pi_2P_{21}=0$.' ],['Detailed balance fails, so stationarity does not imply reversibility.','Cân bằng chi tiết thất bại, nên tính dừng không suy ra thuận nghịch.' ]])
    ],
    reviewNote:'The proof requires row stochasticity for the destination row sum; the directed three-cycle verifies stationarity while disproving reversibility.',
    sourceIds:['f-6041sc']
  },
  'f-w023-e3':{
    application:bi(['Long-run convergence of state probabilities requires both accessibility and freedom from periodic oscillation; irreducibility alone can leave a chain alternating.','Hội tụ xác suất trạng thái dài hạn cần cả khả năng tới nhau và không dao động tuần hoàn; chỉ bất khả quy vẫn có thể luân phiên.']),
    formula:bi(['A finite irreducible chain has a unique stationary distribution; if it is also aperiodic then $P^n(i,\\cdot)\\to\\pi$. Irreducibility alone does not imply this pointwise convergence.','Chuỗi hữu hạn bất khả quy có phân phối dừng duy nhất; nếu còn phi tuần hoàn thì $P^n(i,\\cdot)\\to\\pi$. Riêng bất khả quy không suy ra hội tụ từng thời điểm này.']),
    steps:[bi(['Check whether every state can reach every other state (irreducibility).','Kiểm tra mọi trạng thái có thể tới mọi trạng thái khác không (bất khả quy).' ]),bi(['Check return-time period separately; a deterministic bipartite alternation has period two.','Kiểm tra chu kỳ thời gian quay lại riêng; luân phiên hai phía xác định có chu kỳ hai.' ]),bi(['Use aperiodicity as well as irreducibility for convergence of transition laws from every start.','Dùng cả phi tuần hoàn lẫn bất khả quy để luật chuyển hội tụ từ mọi trạng thái đầu.' ])],
    primarySolution:[bi(['The two-state chain switches state with probability one, so each state reaches the other: it is irreducible.','Chuỗi hai trạng thái đổi trạng thái với xác suất một, nên mỗi trạng thái tới được trạng thái kia: chuỗi bất khả quy.' ]),bi(['Every return to state 1 takes an even number of steps; its return-time gcd is $2$, so the chain is periodic.','Mọi lần quay về trạng thái 1 xảy ra sau số bước chẵn; ước chung các thời gian quay lại là $2$, nên chuỗi tuần hoàn.' ]),bi(['The stationary law is $(1/2,1/2)$, but starting at state 1 gives $\\delta_1P^{2m}=\\delta_1$ and $\\delta_1P^{2m+1}=\\delta_2$.','Luật dừng là $(1/2,1/2)$, nhưng khởi đầu trạng thái 1 cho $\\delta_1P^{2m}=\\delta_1$ và $\\delta_1P^{2m+1}=\\delta_2$.' ]),bi(['Thus the transition distributions oscillate instead of converging, despite irreducibility.','Vì vậy phân phối chuyển dao động thay vì hội tụ dù chuỗi bất khả quy.' ])],
    companions:[
      q(['A deterministic cycle has transition matrix $P=\\begin{pmatrix}0&1&0\\\\0&0&1\\\\1&0&0\\end{pmatrix}$. Find its period and explain why irreducibility does not give convergence from a fixed state.','Chu trình xác định có ma trận chuyển $P=\\begin{pmatrix}0&1&0\\\\0&0&1\\\\1&0&0\\end{pmatrix}$. Tìm chu kỳ và giải thích vì sao bất khả quy không cho hội tụ từ trạng thái cố định.'],[['Every state reaches both others, so the chain is irreducible.','Mỗi trạng thái tới được hai trạng thái còn lại, nên chuỗi bất khả quy.' ],['A return to any state occurs exactly at multiples of three; the period is $3$.','Quay về một trạng thái đúng tại bội số của ba; chu kỳ là $3$.' ],['From state 1, the law cycles among three point masses, so it cannot converge to the uniform stationary law.','Từ trạng thái 1, luật luân phiên ba khối điểm nên không thể hội tụ về luật dừng đều.' ]]),
      q(['For $P=\\begin{pmatrix}0.5&0.5\\\\0.4&0.6\\end{pmatrix}$, identify properties that ensure convergence to the stationary law.','Với $P=\\begin{pmatrix}0.5&0.5\\\\0.4&0.6\\end{pmatrix}$, nêu các tính chất bảo đảm hội tụ về luật dừng.'],[['Both directions have positive transition probability, so the finite chain is irreducible.','Hai hướng đều có xác suất chuyển dương, nên chuỗi hữu hạn bất khả quy.' ],['Each state has a positive self-loop, making its return-time period one.','Mỗi trạng thái có tự lặp dương, làm chu kỳ thời gian quay lại bằng một.' ],['Finite irreducible aperiodic chains satisfy $P^n(i,\\cdot)\\to\\pi$ for every initial state $i$.','Chuỗi hữu hạn bất khả quy phi tuần hoàn thỏa $P^n(i,\\cdot)\\to\\pi$ với mọi trạng thái đầu $i$.' ]]),
      q(['A finite chain has two absorbing states and transitions from state 3 to either one. Is there a unique stationary distribution? Explain by exhibiting stationary laws.','Chuỗi hữu hạn có hai trạng thái hấp thụ và trạng thái 3 chuyển tới một trong hai. Có phân phối dừng duy nhất không? Giải thích bằng các luật dừng.'],[['Each point mass at an absorbing state is stationary.','Khối điểm tại mỗi trạng thái hấp thụ đều là dừng.' ],['Any convex combination $\\lambda\\delta_1+(1-\\lambda)\\delta_2$, $0\\le\\lambda\\le1$, is also stationary by linearity.','Mọi tổ hợp lồi $\\lambda\\delta_1+(1-\\lambda)\\delta_2$, $0\\le\\lambda\\le1$, cũng dừng do tính tuyến tính.' ],['There are multiple stationary distributions because the chain is reducible; irreducibility is essential to the finite-chain uniqueness theorem.','Có nhiều phân phối dừng vì chuỗi khả quy; bất khả quy là thiết yếu trong định lý duy nhất cho chuỗi hữu hạn.' ]])
    ],
    reviewNote:'The two-state flip is irreducible yet period two; convergence is stated only with both finite irreducibility and aperiodicity.',
    sourceIds:['f-6041sc']
  },
  'f-w023-e4':{
    application:bi(['A symmetric random walk on a finite regular network has uniform stationary mass because incoming and outgoing transition totals balance at every node.','Bước đi ngẫu nhiên đối xứng trên mạng hữu hạn đều có khối lượng dừng đều vì tổng xác suất vào và ra cân bằng tại mọi nút.']),
    formula:bi(['If a finite transition matrix is both row- and column-stochastic, then $\\pi_j=1/m$ for $m$ states satisfies $\\pi P=\\pi$.','Nếu ma trận chuyển hữu hạn stochastic theo hàng lẫn cột, thì $\\pi_j=1/m$ với $m$ trạng thái thỏa $\\pi P=\\pi$.']),
    steps:[bi(['Use symmetry plus row sums one to infer column sums one.','Dùng đối xứng và tổng hàng bằng một để suy ra tổng cột bằng một.' ]),bi(['Multiply a uniform row vector by $P$; each output coordinate is the corresponding column sum divided by $m$.','Nhân vectơ hàng đều với $P$; mỗi tọa độ đầu ra là tổng cột tương ứng chia $m$.' ]),bi(['Conclude invariance. Uniqueness requires irreducibility, not merely symmetry.','Kết luận bất biến. Tính duy nhất cần bất khả quy, không chỉ đối xứng.' ])],
    primarySolution:[bi(['For symmetric $P$, $P_{ij}=P_{ji}$. Since each row sums to one, column $j$ also sums to one.','Với $P$ đối xứng, $P_{ij}=P_{ji}$. Vì mỗi hàng có tổng một, cột $j$ cũng có tổng một.' ]),bi(['For uniform $\\pi_i=1/3$, $(\\pi P)_j=(1/3)\\sum_iP_{ij}=1/3$.','Với $\\pi_i=1/3$, $(\\pi P)_j=(1/3)\\sum_iP_{ij}=1/3$.' ]),bi(['Hence the uniform distribution is stationary. The argument establishes stationarity, not uniqueness absent irreducibility.','Vì vậy phân phối đều là dừng. Lập luận chứng minh tính dừng, không chứng minh duy nhất nếu thiếu bất khả quy.' ])],
    companions:[
      q(['Check that $P=\\begin{pmatrix}0.2&0.8\\\\0.8&0.2\\end{pmatrix}$ has the uniform stationary distribution.','Kiểm tra $P=\\begin{pmatrix}0.2&0.8\\\\0.8&0.2\\end{pmatrix}$ có phân phối dừng đều.'],[['Each row and column sums to one.','Mỗi hàng và cột có tổng bằng một.' ],['Multiplying $(1/2,1/2)$ gives $(0.1+0.4,0.4+0.1)=(1/2,1/2)$.','Nhân $(1/2,1/2)$ cho $(0.1+0.4,0.4+0.1)=(1/2,1/2)$.' ],['Thus uniform mass is stationary; positive transitions also make this chain irreducible and aperiodic.','Vậy khối lượng đều là dừng; các chuyển dương cũng làm chuỗi bất khả quy và phi tuần hoàn.' ]]),
      q(['A three-state row-stochastic matrix is symmetric. What is its uniform stationary distribution, and which condition would imply uniqueness?','Ma trận stochastic theo hàng ba trạng thái đối xứng. Phân phối dừng đều là gì, và điều kiện nào suy ra duy nhất?'],[['Symmetry makes column sums equal row sums, hence all columns sum to one.','Đối xứng làm tổng cột bằng tổng hàng, nên mọi cột có tổng một.' ],['Therefore $\\pi=(1/3,1/3,1/3)$ satisfies $(\\pi P)_j=1/3$.','Vì vậy $\\pi=(1/3,1/3,1/3)$ thỏa $(\\pi P)_j=1/3$.' ],['Irreducibility of the finite chain implies uniqueness; symmetry alone does not.','Bất khả quy của chuỗi hữu hạn suy ra duy nhất; riêng đối xứng thì không.' ]]),
      q(['Give a symmetric row-stochastic matrix with more than one stationary distribution, showing why irreducibility matters.','Cho ma trận stochastic theo hàng đối xứng có nhiều hơn một phân phối dừng để thấy vai trò của bất khả quy.'],[['Take $P=I_2$, the two-state identity matrix; it is symmetric and row-stochastic.','Lấy $P=I_2$, ma trận đơn vị hai trạng thái; nó đối xứng và stochastic theo hàng.' ],['Every probability vector $(u,1-u)$ satisfies $(u,1-u)P=(u,1-u)$.','Mọi vectơ xác suất $(u,1-u)$ thỏa $(u,1-u)P=(u,1-u)$.' ],['Thus there are infinitely many stationary distributions; the chain is not irreducible.','Do đó có vô số phân phối dừng; chuỗi không bất khả quy.' ]])
    ],
    reviewNote:'Column sums give invariance; the identity-matrix counterexample confirms irreducibility is needed for uniqueness.',
    sourceIds:['f-6041sc']
  },
  'f-w023-e5':{
    application:bi(['For a chain initialized at equilibrium, expected occupancy of a state over a fixed horizon is the horizon length times its stationary probability, even when visits are dependent.','Với chuỗi khởi đầu ở cân bằng, số lần chiếm một trạng thái kỳ vọng trong thời hạn cố định bằng độ dài thời hạn nhân xác suất dừng, dù các lần ghé phụ thuộc.']),
    formula:bi(['If $X_0\\sim\\pi$ and $\\pi P=\\pi$, then $\\Pr(X_t=j)=\\pi_j$ for each $t$ and $E[\\sum_{t=1}^{T}\\mathbf1\\{X_t=j\\}]=T\\pi_j$.','Nếu $X_0\\sim\\pi$ và $\\pi P=\\pi$, thì $\\Pr(X_t=j)=\\pi_j$ với mọi $t$ và $E[\\sum_{t=1}^{T}\\mathbf1\\{X_t=j\\}]=T\\pi_j$.']),
    steps:[bi(['Invariance propagates the marginal distribution from time $t$ to $t+1$.','Tính bất biến truyền phân phối biên từ thời điểm $t$ sang $t+1$.' ]),bi(['Express each visit count as an indicator and use linearity of expectation.','Viết số lần ghé bằng tổng biến chỉ báo và dùng tính tuyến tính kỳ vọng.' ]),bi(['No independence between time points is needed for this expectation calculation.','Không cần độc lập giữa các thời điểm cho phép tính kỳ vọng này.' ])],
    primarySolution:[bi(['Since $X_0\\sim\\pi$ and $\\pi P=\\pi$, induction gives $X_n\\sim\\pi$ for every $n$.','Vì $X_0\\sim\\pi$ và $\\pi P=\\pi$, quy nạp cho $X_n\\sim\\pi$ với mọi $n$.' ]),bi(['Therefore each indicator $\\mathbf1\\{X_n=j\\}$ has expectation $\\pi_j$.','Vì vậy mỗi chỉ báo $\\mathbf1\\{X_n=j\\}$ có kỳ vọng $\\pi_j$.' ]),bi(['Summing expectations gives $E[\\sum_{n=1}^{T}\\mathbf1\\{X_n=j\\}]=\\sum_{n=1}^T\\pi_j=T\\pi_j$.','Cộng kỳ vọng cho $E[\\sum_{n=1}^{T}\\mathbf1\\{X_n=j\\}]=\\sum_{n=1}^T\\pi_j=T\\pi_j$.' ])],
    companions:[
      q(['A stationary chain has $\\pi_3=0.2$. Find the expected number of visits to state 3 at times 1 through 40.','Chuỗi dừng có $\\pi_3=0.2$. Tìm số lần kỳ vọng ghé trạng thái 3 tại thời điểm 1 đến 40.'],[['At each indexed time, stationarity gives visit probability $0.2$.','Ở mỗi thời điểm được đánh chỉ số, tính dừng cho xác suất ghé $0.2$.' ],['The expected count is the sum of 40 indicator expectations: $40(0.2)=8$.','Số lần kỳ vọng là tổng kỳ vọng của 40 chỉ báo: $40(0.2)=8$.' ],['This uses linearity, not independence of visits.','Phép tính dùng tính tuyến tính, không cần các lần ghé độc lập.' ]]),
      q(['A stationary two-state chain has $\\pi=(0.7,0.3)$. Find the expected number of state-2 visits over times 0 through 9.','Chuỗi dừng hai trạng thái có $\\pi=(0.7,0.3)$. Tìm số lần kỳ vọng ghé trạng thái 2 từ thời điểm 0 đến 9.'],[['The interval includes 10 time indices.','Khoảng gồm 10 thời điểm.' ],['Each has state-2 probability $0.3$, so the expected count is $10(0.3)=3$.','Mỗi thời điểm có xác suất trạng thái 2 bằng $0.3$, nên số lần kỳ vọng là $10(0.3)=3$.' ],['The inclusive endpoints explain the factor 10.','Hai đầu mút đều tính nên hệ số là 10.' ]]),
      q(['For any initial distribution $\\nu$, express the expected number of state-$j$ visits through time $T$ without assuming stationarity.','Với phân phối đầu bất kỳ $\\nu$, biểu diễn số lần kỳ vọng ghé trạng thái $j$ đến thời điểm $T$ mà không giả sử dừng.'],[['At time $t$, the distribution is $\\nu P^t$.','Tại thời điểm $t$, phân phối là $\\nu P^t$.' ],['Thus $\\Pr(X_t=j)=(\\nu P^t)_j$.','Vì vậy $\\Pr(X_t=j)=(\\nu P^t)_j$.' ],['By indicator linearity, expected visits at times 1 through $T$ equal $\\sum_{t=1}^T(\\nu P^t)_j$; the simpler $T\\pi_j$ formula needs stationary initialization.','Theo tính tuyến tính chỉ báo, số lần kỳ vọng từ thời điểm 1 đến $T$ là $\\sum_{t=1}^T(\\nu P^t)_j$; công thức gọn $T\\pi_j$ cần khởi tạo dừng.' ]])
    ],
    reviewNote:'Expected occupancy uses stationary marginals and indicator linearity; it makes no independence or ergodic-convergence claim.',
    sourceIds:['f-6041sc']
  },
  'f-w024-e1':{
    application:bi(['A forecasting method is judged by squared error; the mean squared error decomposes into random spread plus squared systematic bias.','Phương pháp dự báo được đánh giá bằng sai số bình phương; MSE phân rã thành độ biến thiên ngẫu nhiên cộng bình phương độ chệch hệ thống.']),
    formula:bi(['If $E[\\hat\\theta^2]<\\infty$, then $\\operatorname{MSE}(\\hat\\theta)=E[(\\hat\\theta-\\theta)^2]=\\operatorname{Var}(\\hat\\theta)+(E\\hat\\theta-\\theta)^2$.','Nếu $E[\\hat\\theta^2]<\\infty$, thì $\\operatorname{MSE}(\\hat\\theta)=E[(\\hat\\theta-\\theta)^2]=\\operatorname{Var}(\\hat\\theta)+(E\\hat\\theta-\\theta)^2$.']),
    steps:[bi(['Add and subtract $E\\hat\\theta$ inside the estimation error.','Cộng và trừ $E\\hat\\theta$ trong sai số ước lượng.' ]),bi(['Square the centered-random part plus the constant bias.','Bình phương phần ngẫu nhiên đã tâm cộng với độ chệch hằng.' ]),bi(['The cross term vanishes because $E[\\hat\\theta-E\\hat\\theta]=0$.','Số hạng chéo mất đi vì $E[\\hat\\theta-E\\hat\\theta]=0$.' ])],
    primarySolution:[bi(['Write $\\hat\\theta-\\theta=(\\hat\\theta-E\\hat\\theta)+(E\\hat\\theta-\\theta)$.','Viết $\\hat\\theta-\\theta=(\\hat\\theta-E\\hat\\theta)+(E\\hat\\theta-\\theta)$.' ]),bi(['Squaring and taking expectation gives variance, twice the bias times a zero-mean term, and bias squared.','Bình phương rồi lấy kỳ vọng cho phương sai, hai lần độ chệch nhân số hạng kỳ vọng không, và độ chệch bình phương.' ]),bi(['Therefore $\\operatorname{MSE}=\\operatorname{Var}(\\hat\\theta)+(E\\hat\\theta-\\theta)^2$, assuming the second moment exists.','Vì vậy $\\operatorname{MSE}=\\operatorname{Var}(\\hat\\theta)+(E\\hat\\theta-\\theta)^2$, với giả thiết moment bậc hai tồn tại.' ])],
    companions:[
      q(['An estimator has mean $7$ for target $\\theta=5$ and variance $3$. Find its bias and MSE.','Một ước lượng có kỳ vọng $7$ cho mục tiêu $\\theta=5$ và phương sai $3$. Tìm độ chệch và MSE.'],[['Bias is $E\\hat\\theta-\\theta=7-5=2$.','Độ chệch là $E\\hat\\theta-\\theta=7-5=2$.' ],['The squared bias is $4$, so MSE is $3+4=7$.','Bình phương độ chệch là $4$, nên MSE bằng $3+4=7$.' ],['The variance measures spread around the estimator mean; the bias accounts for its offset from the target.','Phương sai đo độ phân tán quanh kỳ vọng ước lượng; độ chệch tính độ lệch khỏi mục tiêu.' ]]),
      q(['Let $X$ take values $0$ and $2$ with equal probability and estimate its mean $1$ by $\\hat\\theta=X+1$. Compute bias, variance, and MSE.','Cho $X$ nhận $0$ và $2$ với xác suất bằng nhau, ước lượng kỳ vọng $1$ bằng $\\hat\\theta=X+1$. Tính độ chệch, phương sai và MSE.'],[['The estimator takes $1$ or $3$, so $E\\hat\\theta=2$ and bias is $1$.','Ước lượng nhận $1$ hoặc $3$, nên $E\\hat\\theta=2$ và độ chệch là $1$.' ],['Adding a constant leaves variance unchanged: $\\operatorname{Var}(\\hat\\theta)=\\operatorname{Var}(X)=1$.','Cộng hằng số không đổi phương sai: $\\operatorname{Var}(\\hat\\theta)=\\operatorname{Var}(X)=1$.' ],['MSE is $1+1^2=2$; directly, errors are $0$ and $2$, whose squared average is also $2$.','MSE là $1+1^2=2$; trực tiếp, sai số là $0$ và $2$, trung bình bình phương cũng bằng $2$.' ]]),
      q(['Estimator A has bias $-1$ and variance $2$; estimator B is unbiased with variance $4$. Compare MSE under squared-error loss.','Ước lượng A có độ chệch $-1$ và phương sai $2$; B không chệch, phương sai $4$. So sánh MSE theo mất mát bình phương.'],[['For A, MSE is $2+(-1)^2=3$.','Với A, MSE là $2+(-1)^2=3$.' ],['For B, MSE is $4+0=4$.','Với B, MSE là $4+0=4$.' ],['A has smaller squared-error risk despite being biased; unbiasedness alone does not rank estimators.','A có rủi ro bình phương nhỏ hơn dù bị chệch; riêng tính không chệch không xếp hạng được ước lượng.' ]])
    ],
    reviewNote:'Expanded the squared error under a finite second moment; checked each bias sign and MSE comparison.',
    sourceIds:['f-1805']
  },
  'f-w024-e2':{
    application:bi(['A known-noise measurement model produces a confidence interval for the population mean by scaling the sampling standard deviation with a normal quantile.','Mô hình đo lường nhiễu đã biết tạo khoảng tin cậy cho trung bình tổng thể bằng cách nhân độ lệch chuẩn lấy mẫu với phân vị chuẩn.']),
    formula:bi(['For IID $N(\\mu,\\sigma^2)$ data with known $\\sigma$, $\\bar X\\pm z_{1-\\alpha/2}\\sigma/\\sqrt n$ has exact coverage $1-\\alpha$; with nonnormal IID finite-variance data it is generally a large-sample CLT approximation.','Với dữ liệu IID $N(\\mu,\\sigma^2)$ đã biết $\\sigma$, khoảng $\\bar X\\pm z_{1-\\alpha/2}\\sigma/\\sqrt n$ có độ phủ chính xác $1-\\alpha$; dữ liệu IID không chuẩn phương sai hữu hạn thường chỉ cho xấp xỉ CLT khi mẫu lớn.']),
    steps:[bi(['Compute the standard error $\\sigma/\\sqrt n$.','Tính sai số chuẩn $\\sigma/\\sqrt n$.' ]),bi(['Multiply by the two-sided normal critical value.','Nhân với giá trị tới hạn chuẩn hai phía.' ]),bi(['Add and subtract this margin from $\\bar X$; identify whether coverage is exact or approximate from the model assumptions.','Cộng trừ biên này khỏi $\\bar X$; xác định độ phủ chính xác hay xấp xỉ theo giả thiết mô hình.' ])],
    primarySolution:[bi(['The standard error is $4/\\sqrt{64}=4/8=0.5$.','Sai số chuẩn là $4/\\sqrt{64}=4/8=0.5$.' ]),bi(['The 95% margin is $1.96(0.5)=0.98$.','Biên 95% là $1.96(0.5)=0.98$.' ]),bi(['The interval is $10\\pm0.98=[9.02,10.98]$. It is exact under IID normal sampling with known $\\sigma$; under the stated CLT conditions it is approximate.','Khoảng là $10\\pm0.98=[9.02,10.98]$. Khoảng chính xác với lấy mẫu chuẩn IID và biết $\\sigma$; theo điều kiện CLT đã nêu thì là xấp xỉ.' ])],
    companions:[
      q(['For IID normal observations with known $\\sigma=3$, $n=36$, and $\\bar X=12$, compute the exact 95% interval using $z=1.96$.','Với quan sát chuẩn IID biết $\\sigma=3$, $n=36$, $\\bar X=12$, tính khoảng chính xác 95% với $z=1.96$.'],[['The standard error is $3/\\sqrt{36}=0.5$.','Sai số chuẩn là $3/\\sqrt{36}=0.5$.' ],['The margin is $1.96(0.5)=0.98$.','Biên sai số là $1.96(0.5)=0.98$.' ],['Endpoints are $12-0.98=11.02$ and $12+0.98=12.98$; normality makes coverage exact.','Hai đầu mút là $12-0.98=11.02$ và $12+0.98=12.98$; tính chuẩn làm độ phủ chính xác.' ]]),
      q(['An IID sample with finite variance has $\\bar X=5$, known population standard deviation $\\sigma=2$, and $n=100$. Give a large-sample 95% interval and label its status.','Mẫu IID có phương sai hữu hạn, $\\bar X=5$, độ lệch chuẩn tổng thể biết $\\sigma=2$, $n=100$. Cho khoảng 95% mẫu lớn và ghi trạng thái.'],[['The estimated standard error using the known $\\sigma$ is $2/10=0.2$.','Sai số chuẩn dùng $\\sigma$ đã biết là $2/10=0.2$.' ],['The normal margin is $1.96(0.2)=0.392$.','Biên chuẩn là $1.96(0.2)=0.392$.' ],['The interval is $[4.608,5.392]$, an asymptotic CLT interval unless the population is normal.','Khoảng là $[4.608,5.392]$, xấp xỉ tiệm cận CLT trừ khi tổng thể chuẩn.' ]]),
      q(['If $\\sigma=5$ and $n=25$, by what factor does the 95% margin change when sample size increases to $100$?','Nếu $\\sigma=5$ và $n=25$, biên 95% thay đổi theo hệ số nào khi tăng cỡ mẫu lên $100$?'],[['Initially the standard error is $5/5=1$.','Ban đầu sai số chuẩn là $5/5=1$.' ],['At $n=100$ it is $5/10=0.5$.','Ở $n=100$, sai số chuẩn là $5/10=0.5$.' ],['The critical value is fixed, so the margin halves; quadrupling $n$ halves the standard error.','Giá trị tới hạn cố định nên biên giảm một nửa; tăng gấp bốn $n$ làm sai số chuẩn giảm nửa.' ]])
    ],
    reviewNote:'Checked standard-error scaling and endpoints; exactness is restricted to normal IID known-variance sampling.',
    sourceIds:['f-1805']
  },
  'f-w024-e3':{
    application:bi(['A prediction interval must cover a future individual measurement, which varies around the mean as well as because the mean is estimated.','Khoảng dự đoán phải bao phủ phép đo cá nhân tương lai, biến thiên quanh trung bình và do trung bình được ước lượng.']),
    formula:bi(['For IID observations with finite variance, $X_{n+1}$ independent of $\\bar X_n$, and variance $\\sigma^2$, $\\operatorname{Var}(X_{n+1}-\\bar X_n)=\\sigma^2(1+1/n)$.','Với quan sát IID phương sai hữu hạn, $X_{n+1}$ độc lập với $\\bar X_n$, và phương sai $\\sigma^2$, $\\operatorname{Var}(X_{n+1}-\\bar X_n)=\\sigma^2(1+1/n)$.']),
    steps:[bi(['State the independent future-observation assumption.','Nêu giả thiết quan sát tương lai độc lập.' ]),bi(['Use $\\operatorname{Var}(X_{n+1}-\\bar X_n)=\\operatorname{Var}(X_{n+1})+\\operatorname{Var}(\\bar X_n)$.','Dùng $\\operatorname{Var}(X_{n+1}-\\bar X_n)=\\operatorname{Var}(X_{n+1})+\\operatorname{Var}(\\bar X_n)$.' ]),bi(['The individual component contributes $\\sigma^2$, making prediction uncertainty larger than mean uncertainty $\\sigma^2/n$.','Thành phần cá nhân góp $\\sigma^2$, làm bất định dự đoán lớn hơn bất định trung bình $\\sigma^2/n$.' ])],
    primarySolution:[bi(['Independence of a future IID observation and the sample gives $\\operatorname{Cov}(X_{n+1},\\bar X_n)=0$.','Độc lập giữa quan sát IID tương lai và mẫu cho $\\operatorname{Cov}(X_{n+1},\\bar X_n)=0$.' ]),bi(['Thus the difference variance is $\\sigma^2+\\operatorname{Var}(\\bar X_n)=\\sigma^2+\\sigma^2/n$.','Vậy phương sai hiệu là $\\sigma^2+\\operatorname{Var}(\\bar X_n)=\\sigma^2+\\sigma^2/n$.' ]),bi(['Factor to obtain $\\sigma^2(1+1/n)$, which exceeds $\\sigma^2/n$ for a mean interval.','Đưa nhân tử được $\\sigma^2(1+1/n)$, lớn hơn $\\sigma^2/n$ của khoảng trung bình.' ])],
    companions:[
      q(['Under IID normal sampling with known $\\sigma=3$ and $n=8$, compute the standard error for predicting one future observation relative to $\\bar X$.','Với mẫu chuẩn IID biết $\\sigma=3$ và $n=8$, tính sai số chuẩn dự đoán một quan sát tương lai quanh $\\bar X$.'],[['The variance of the prediction error is $9(1+1/8)=81/8$.','Phương sai sai số dự đoán là $9(1+1/8)=81/8$.' ],['Take the square root: $\\operatorname{SE}=9/\\sqrt8\\approx3.182$.','Lấy căn: $\\operatorname{SE}=9/\\sqrt8\\approx3.182$.' ],['This exceeds the mean SE $3/\\sqrt8$ because it includes future observation noise.','Giá trị này lớn hơn SE trung bình $3/\\sqrt8$ vì có thêm nhiễu quan sát tương lai.' ]]),
      q(['For $n=4$ and variance $\\sigma^2=16$, compare the mean-estimation variance with prediction-error variance.','Với $n=4$ và phương sai $\\sigma^2=16$, so sánh phương sai ước lượng trung bình với phương sai sai số dự đoán.'],[['The variance of $\\bar X$ is $16/4=4$.','Phương sai của $\\bar X$ là $16/4=4$.' ],['The future prediction-error variance is $16(1+1/4)=20$.','Phương sai sai số dự đoán tương lai là $16(1+1/4)=20$.' ],['The additional $16$ comes from the unpredictable future draw itself.','Phần cộng thêm $16$ đến từ phép rút tương lai không thể dự đoán.' ]]),
      q(['If the future value is correlated with the sample mean with covariance $c$, derive the variance of $X_{n+1}-\\bar X_n$.','Nếu giá trị tương lai tương quan với trung bình mẫu với hiệp phương sai $c$, suy ra phương sai của $X_{n+1}-\\bar X_n$.'],[['Use $\\operatorname{Var}(A-B)=\\operatorname{Var}(A)+\\operatorname{Var}(B)-2\\operatorname{Cov}(A,B)$.','Dùng $\\operatorname{Var}(A-B)=\\operatorname{Var}(A)+\\operatorname{Var}(B)-2\\operatorname{Cov}(A,B)$.' ],['The marginal variances are $\\sigma^2$ and $\\sigma^2/n$.','Các phương sai biên là $\\sigma^2$ và $\\sigma^2/n$.' ],['Therefore the result is $\\sigma^2+\\sigma^2/n-2c$; IID independence gives $c=0$.','Vì vậy kết quả là $\\sigma^2+\\sigma^2/n-2c$; độc lập IID cho $c=0$.' ]])
    ],
    reviewNote:'The prediction-error formula assumes the future observation is independent of the IID training sample; covariance is shown explicitly in the transfer problem.',
    sourceIds:['f-1805']
  },
  'f-w024-e4':{
    application:bi(['Estimator choice depends on loss, not on unbiasedness alone; under squared-error loss the variance-bias tradeoff is summarized by MSE.','Chọn ước lượng phụ thuộc mất mát, không chỉ tính không chệch; dưới mất mát bình phương, đánh đổi phương sai-độ chệch được tóm tắt bằng MSE.']),
    formula:bi(['For finite second moments, $\\operatorname{MSE}(\\hat\\theta)=\\operatorname{Var}(\\hat\\theta)+\\operatorname{Bias}(\\hat\\theta)^2$ and $\\operatorname{RMSE}=\\sqrt{\\operatorname{MSE}}$.','Với moment bậc hai hữu hạn, $\\operatorname{MSE}(\\hat\\theta)=\\operatorname{Var}(\\hat\\theta)+\\operatorname{Bias}(\\hat\\theta)^2$ và $\\operatorname{RMSE}=\\sqrt{\\operatorname{MSE}}$.']),
    steps:[bi(['Compute each estimator’s squared bias.','Tính bình phương độ chệch của mỗi ước lượng.' ]),bi(['Add it to variance to obtain MSE.','Cộng vào phương sai để được MSE.' ]),bi(['Take square roots only for RMSE; compare the requested loss criterion.','Chỉ lấy căn khi tính RMSE; so sánh theo tiêu chí mất mát được hỏi.' ])],
    primarySolution:[bi(['For A, bias is zero, so $\\operatorname{MSE}_A=4$ and $\\operatorname{RMSE}_A=\\sqrt4=2$.','Với A, độ chệch bằng không nên $\\operatorname{MSE}_A=4$ và $\\operatorname{RMSE}_A=\\sqrt4=2$.' ]),bi(['For B, $\\operatorname{MSE}_B=1+1^2=2$, and $\\operatorname{RMSE}_B=\\sqrt2$.','Với B, $\\operatorname{MSE}_B=1+1^2=2$ và $\\operatorname{RMSE}_B=\\sqrt2$.' ]),bi(['B has smaller squared-error risk even though it is biased; A’s unbiasedness does not make it preferable under this loss.','B có rủi ro bình phương nhỏ hơn dù bị chệch; A không tự tốt hơn chỉ vì không chệch theo mất mát này.' ])],
    companions:[
      q(['Estimator C has variance $0.5$ and bias $1.5$; estimator D has variance $3$ and bias $0$. Which has smaller RMSE?','Ước lượng C có phương sai $0.5$, độ chệch $1.5$; D có phương sai $3$, độ chệch $0$. Ước lượng nào có RMSE nhỏ hơn?'],[['C has MSE $0.5+1.5^2=2.75$.','C có MSE $0.5+1.5^2=2.75$.' ],['D has MSE $3+0=3$.','D có MSE $3+0=3$.' ],['Because square root preserves order, C has smaller RMSE: $\\sqrt{2.75}<\\sqrt3$.','Vì căn bậc hai bảo toàn thứ tự, C có RMSE nhỏ hơn: $\\sqrt{2.75}<\\sqrt3$.' ]]),
      q(['An estimator is unbiased with variance $9$. Another has bias $2$ and variance $1$. Compare their MSE and identify the better one for squared error.','Một ước lượng không chệch có phương sai $9$. Ước lượng khác có độ chệch $2$, phương sai $1$. So sánh MSE và chọn theo sai số bình phương.'],[['The unbiased estimator has MSE $9$.','Ước lượng không chệch có MSE $9$.' ],['The biased estimator has MSE $1+2^2=5$.','Ước lượng bị chệch có MSE $1+2^2=5$.' ],['The second is preferable under squared-error loss because $5<9$.','Ước lượng thứ hai tốt hơn theo mất mát bình phương vì $5<9$.' ]]),
      q(['Can RMSE be negative? Explain using the relation to MSE and state what quantity retains units of the parameter.','RMSE có thể âm không? Giải thích qua quan hệ với MSE và nêu đại lượng giữ cùng đơn vị với tham số.'],[['MSE is an expectation of squared errors and is therefore nonnegative.','MSE là kỳ vọng sai số bình phương nên không âm.' ],['RMSE is its nonnegative square root, so it cannot be negative.','RMSE là căn bậc hai không âm nên không thể âm.' ],['Squared errors and MSE have squared units; RMSE returns to the parameter’s units.','Sai số bình phương và MSE có đơn vị bình phương; RMSE trở về đơn vị của tham số.' ]])
    ],
    reviewNote:'Checked the squared-bias term, RMSE square roots, and rankings under squared-error loss.',
    sourceIds:['f-1805']
  },
  'f-w024-e5':{
    application:bi(['Repeated-sampling coverage audits whether a confidence procedure reaches its advertised rate; it does not assign posterior probability to a fixed parameter after one interval is observed.','Kiểm toán độ phủ lấy mẫu lặp đánh giá thủ tục khoảng có đạt tỷ lệ công bố không; nó không gán xác suất hậu nghiệm cho tham số cố định sau khi thấy một khoảng.']),
    formula:bi(['Empirical coverage over $M$ repeated samples is $M^{-1}\\sum_{m=1}^M\\mathbf1\\{\\theta\\in C_m\\}$; nominal $1-\\alpha$ is a long-run procedure property under the model.','Độ phủ thực nghiệm qua $M$ mẫu lặp là $M^{-1}\\sum_{m=1}^M\\mathbf1\\{\\theta\\in C_m\\}$; mức danh nghĩa $1-\\alpha$ là tính chất dài hạn của thủ tục theo mô hình.']),
    steps:[bi(['Count intervals that contain the fixed parameter.','Đếm các khoảng chứa tham số cố định.' ]),bi(['Divide by the total number of repeated intervals.','Chia cho tổng số khoảng lặp.' ]),bi(['Interpret the nominal level over repeated sampling, not as a posterior probability for one realized interval.','Diễn giải mức danh nghĩa qua lấy mẫu lặp, không phải xác suất hậu nghiệm của một khoảng đã quan sát.' ])],
    primarySolution:[bi(['The empirical fraction is $918/1000=0.918$.','Tỷ lệ thực nghiệm là $918/1000=0.918$.' ]),bi(['As a percentage this is $91.8\\%$, below the nominal $95\\%$ in this finite simulation.','Đổi ra phần trăm là $91.8\\%$, thấp hơn mức danh nghĩa $95\\%$ trong mô phỏng hữu hạn này.' ]),bi(['The $95\\%$ claim describes the repeated-sampling coverage of the procedure under its assumptions; it is not $\\Pr(\\theta\\in C\\mid C)$ for the one observed interval.','Khẳng định $95\\%$ mô tả độ phủ lấy mẫu lặp của thủ tục theo giả thiết; không phải $\\Pr(\\theta\\in C\\mid C)$ cho khoảng duy nhất đã quan sát.' ])],
    companions:[
      q(['Across 2,000 repeated samples, a nominal 90% interval contains the fixed parameter 1,786 times. Find empirical coverage and compare it to nominal.','Qua 2.000 mẫu lặp, khoảng danh nghĩa 90% chứa tham số cố định 1.786 lần. Tính độ phủ thực nghiệm và so với danh nghĩa.'],[['Compute $1786/2000=0.893$.','Tính $1786/2000=0.893$.' ],['As a percent this is $89.3\\%$, which is $0.7$ percentage points below nominal.','Đổi phần trăm được $89.3\\%$, thấp hơn danh nghĩa $0.7$ điểm phần trăm.' ],['Finite simulation variation can explain some discrepancy; this estimate alone does not prove systematic undercoverage.','Biến thiên mô phỏng hữu hạn có thể giải thích một phần sai khác; riêng ước lượng này không chứng minh thiếu phủ có hệ thống.' ]]),
      q(['In a frequentist model, after observing a particular 95% interval $[2.1,3.4]$, what is random across repetitions and what is fixed?','Trong mô hình tần suất, sau khi quan sát khoảng 95% cụ thể $[2.1,3.4]$, đại lượng nào ngẫu nhiên qua lặp và đại lượng nào cố định?'],[['The parameter $\\theta$ is fixed, while the interval endpoints vary with the random sample.','Tham số $\\theta$ cố định, còn đầu mút khoảng thay đổi theo mẫu ngẫu nhiên.' ],['Before sampling, the procedure has 95% coverage under its stated assumptions.','Trước lấy mẫu, thủ tục có độ phủ 95% theo các giả thiết đã nêu.' ],['After this interval is observed, frequentist coverage does not mean a 95% posterior chance that this fixed interval contains $\\theta$.','Sau khi quan sát khoảng này, độ phủ tần suất không có nghĩa khoảng cố định này chứa $\\theta$ với xác suất hậu nghiệm 95%.' ]]),
      q(['A procedure covers in 96 of 100 trials. Explain why this does not establish exact 96% coverage or invalidate a nominal 95% procedure.','Thủ tục phủ trong 96 trên 100 lần thử. Giải thích vì sao điều này không xác lập độ phủ chính xác 96% hoặc bác bỏ thủ tục danh nghĩa 95%.'],[['The observed fraction is $96/100=0.96$, a noisy estimate based on only 100 repetitions.','Tỷ lệ quan sát là $96/100=0.96$, ước lượng nhiễu từ chỉ 100 lần lặp.' ],['Repeated-sampling coverage is a model probability, while the empirical fraction fluctuates around it.','Độ phủ lấy mẫu lặp là xác suất mô hình, còn tỷ lệ thực nghiệm dao động quanh nó.' ],['A value above 95% is compatible with a nominal 95% procedure; many more repetitions or an exact analysis are needed to assess calibration.','Giá trị cao hơn 95% tương thích thủ tục danh nghĩa 95%; cần nhiều lần lặp hơn hoặc phân tích chính xác để đánh giá hiệu chỉnh.' ]])
    ],
    reviewNote:'Coverage arithmetic is exact; the interpretation treats θ as fixed and the interval as random before sampling.',
    sourceIds:['f-1805']
  },
  'f-w025-e1':{
    application:bi(['Reliability lifetimes often use an exponential rate; maximizing the likelihood requires checking the data support and whether the optimum lies at a finite interior parameter.','Thời gian sống trong độ tin cậy thường dùng tốc độ mũ; tối đa hóa hợp lý cần kiểm tra miền dữ liệu và nghiệm tối ưu có nằm ở tham số nội tại hữu hạn không.']),
    formula:bi(['For IID $X_i\\sim\\operatorname{Exp}(\\lambda)$ on $[0,\\infty)$, if $S=\\sum_i x_i>0$, $\\ell(\\lambda)=n\\log\\lambda-\\lambda S$ and $\\hat\\lambda=n/S$; if $S=0$, no finite maximizer exists over $\\lambda>0$.','Với $X_i\\sim\\operatorname{Exp}(\\lambda)$ IID trên $[0,\\infty)$, nếu $S=\\sum_i x_i>0$, $\\ell(\\lambda)=n\\log\\lambda-\\lambda S$ và $\\hat\\lambda=n/S$; nếu $S=0$, không có cực đại hữu hạn trên $\\lambda>0$.']),
    steps:[bi(['Write the likelihood $L(\\lambda)=\\lambda^n e^{-\\lambda S}$ for nonnegative observations.','Viết hợp lý $L(\\lambda)=\\lambda^n e^{-\\lambda S}$ cho quan sát không âm.' ]),bi(['When $S>0$, differentiate the log likelihood and check its second derivative.','Khi $S>0$, lấy đạo hàm log-hợp-lý và kiểm tra đạo hàm bậc hai.' ]),bi(['When $S=0$, inspect the boundary behavior as $\\lambda\\to\\infty$ rather than using an invalid stationary-point formula.','Khi $S=0$, xét hành vi biên khi $\\lambda\\to\\infty$ thay vì dùng công thức điểm dừng không hợp lệ.' ])],
    primarySolution:[bi(['For $S>0$, $\\ell(\\lambda)=n\\log\\lambda-\\lambda S$ and $\\ell^{\\prime}(\\lambda)=n/\\lambda-S$.','Với $S>0$, $\\ell(\\lambda)=n\\log\\lambda-\\lambda S$ và $\\ell^{\\prime}(\\lambda)=n/\\lambda-S$.' ]),bi(['Setting the derivative to zero gives $\\hat\\lambda=n/S$; $\\ell^{\\prime\\prime}(\\lambda)=-n/\\lambda^2<0$ verifies a maximum.','Cho đạo hàm bằng không được $\\hat\\lambda=n/S$; $\\ell^{\\prime\\prime}(\\lambda)=-n/\\lambda^2<0$ xác nhận cực đại.' ]),bi(['If $S=0$, then $L(\\lambda)=\\lambda^n$ grows without bound as $\\lambda\\to\\infty$, so the open parameter space has no finite maximizer.','Nếu $S=0$, thì $L(\\lambda)=\\lambda^n$ tăng vô hạn khi $\\lambda\\to\\infty$, nên miền tham số mở không có cực đại hữu hạn.' ])],
    companions:[
      q(['For exponential observations with $n=5$ and observed sum $S=10$, find the rate MLE and verify the curvature.','Với quan sát mũ có $n=5$ và tổng quan sát $S=10$, tìm MLE tốc độ và kiểm tra độ cong.'],[['The log likelihood is $5\\log\\lambda-10\\lambda$.','Log-hợp-lý là $5\\log\\lambda-10\\lambda$.' ],['Its derivative $5/\\lambda-10$ vanishes at $\\hat\\lambda=0.5$.','Đạo hàm $5/\\lambda-10$ bằng không tại $\\hat\\lambda=0.5$.' ],['Second derivative $-5/\\lambda^2<0$ confirms a maximum; the positive sum ensures a finite estimate.','Đạo hàm bậc hai $-5/\\lambda^2<0$ xác nhận cực đại; tổng dương bảo đảm ước lượng hữu hạn.' ]]),
      q(['Three exponential observations are all zero. Describe the likelihood behavior and the MLE status.','Ba quan sát mũ đều bằng không. Mô tả hành vi hợp lý và trạng thái MLE.'],[['The sum is $S=0$, so $L(\\lambda)=\\lambda^3$.','Tổng là $S=0$, nên $L(\\lambda)=\\lambda^3$.' ],['For every finite $\\lambda$ the likelihood can be increased by choosing a larger rate.','Với mọi $\\lambda$ hữu hạn, có thể tăng hợp lý bằng cách chọn tốc độ lớn hơn.' ],['Thus the supremum is infinite and no finite maximizer exists on $\\lambda>0$.','Vì vậy supremum vô hạn và không có cực đại hữu hạn trên $\\lambda>0$.' ]]),
      q(['For $n=4$ exponential data with sample mean $2$, compute the rate MLE and compare it to the scale estimate.','Với dữ liệu mũ $n=4$ có trung bình mẫu $2$, tính MLE tốc độ và so với ước lượng thang.'],[['The sum is $S=n\\bar X=4(2)=8$.','Tổng là $S=n\\bar X=4(2)=8$.' ],['The rate MLE is $n/S=4/8=0.5=1/\\bar X$.','MLE tốc độ là $n/S=4/8=0.5=1/\\bar X$.' ],['The value $\\bar X=2$ estimates the scale/mean, not the rate; confusing them takes a reciprocal.','Giá trị $\\bar X=2$ ước lượng thang/trung bình, không phải tốc độ; nhầm chúng sẽ lấy sai nghịch đảo.' ]])
    ],
    reviewNote:'Checked the likelihood on λ>0; S>0 yields the finite concave maximum n/S, while S=0 gives an unbounded likelihood.',
    sourceIds:['f-1805']
  },
  'f-w025-e2':{
    application:bi(['At extreme observed counts, the Bernoulli likelihood can peak on the parameter-space boundary rather than at an interior derivative solution.','Với số đếm quan sát cực trị, hợp lý Bernoulli có thể đạt đỉnh ở biên miền tham số thay vì nghiệm đạo hàm nội tại.']),
    formula:bi(['For $n$ Bernoulli observations with $S=\\sum X_i$, $L(p)=p^S(1-p)^{n-S}$ on $p\\in[0,1]$; if $S=0$, it is maximized at $\\hat p=0$.','Với $n$ quan sát Bernoulli có $S=\\sum X_i$, $L(p)=p^S(1-p)^{n-S}$ trên $p\\in[0,1]$; nếu $S=0$, cực đại tại $\\hat p=0$.']),
    steps:[bi(['Substitute the observed success count $S$ in the likelihood.','Thay số thành công quan sát $S$ vào hợp lý.' ]),bi(['For $S=0$, simplify to $(1-p)^n$.','Với $S=0$, rút gọn thành $(1-p)^n$.' ]),bi(['This decreases on $[0,1]$, so inspect and include the endpoint $p=0$.','Hàm giảm trên $[0,1]$, nên kiểm tra và đưa đầu mút $p=0$ vào.' ])],
    primarySolution:[bi(['With $S=0$, $L(p)=p^0(1-p)^n=(1-p)^n$.','Với $S=0$, $L(p)=p^0(1-p)^n=(1-p)^n$.' ]),bi(['For $p\\in[0,1]$, this likelihood is at most $1$ and equals $1$ at $p=0$.','Với $p\\in[0,1]$, hợp lý không quá $1$ và bằng $1$ tại $p=0$.' ]),bi(['Thus the boundary MLE is $\\hat p=0$; an interior log-likelihood derivative is not needed.','Vậy MLE biên là $\\hat p=0$; không cần dùng đạo hàm log-hợp-lý nội tại.' ])],
    companions:[
      q(['For $n=6$ Bernoulli trials with all successes, find the MLE over $p\\in[0,1]$.','Với $n=6$ phép thử Bernoulli đều thành công, tìm MLE trên $p\\in[0,1]$.'],[['Here $S=6$, so $L(p)=p^6$.','Ở đây $S=6$, nên $L(p)=p^6$.' ],['This increases on $[0,1]$.','Hàm tăng trên $[0,1]$.' ],['Its maximum is at $p=1$, so $\\hat p=1$.','Cực đại tại $p=1$, nên $\\hat p=1$.' ]]),
      q(['For $n=10$ trials with $S=2$ successes, derive the interior Bernoulli MLE.','Với $n=10$ phép thử có $S=2$ lần thành công, suy ra MLE Bernoulli nội tại.'],[['The log likelihood is $\\ell(p)=2\\log p+8\\log(1-p)$ for $0<p<1$.','Log-hợp-lý là $\\ell(p)=2\\log p+8\\log(1-p)$ với $0<p<1$.' ],['Set $\\ell^{\\prime}(p)=2/p-8/(1-p)=0$, giving $2(1-p)=8p$.','Cho $\\ell^{\\prime}(p)=2/p-8/(1-p)=0$, được $2(1-p)=8p$.' ],['Thus $\\hat p=2/10=0.2$; concavity of the log likelihood makes it the maximum.','Vậy $\\hat p=2/10=0.2$; tính lõm của log-hợp-lý cho đây là cực đại.' ]]),
      q(['Explain why using the formula $S/n$ still yields a valid MLE at both all-failure and all-success boundaries.','Giải thích vì sao công thức $S/n$ vẫn cho MLE hợp lệ tại cả biên toàn thất bại và toàn thành công.'],[['The likelihood for general $S$ is maximized at $p=S/n$ when $0<S<n$.','Hợp lý với $S$ tổng quát đạt cực đại tại $p=S/n$ khi $0<S<n$.' ],['At $S=0$, this formula gives $p=0$, which direct endpoint inspection confirms; at $S=n$, it gives $p=1$, also confirmed at the endpoint.','Khi $S=0$, công thức cho $p=0$, được kiểm tra trực tiếp ở biên; khi $S=n$, cho $p=1$, cũng được xác nhận ở biên.' ],['Thus the compact formula includes boundary optima when parameter space includes $[0,1]$.','Vì vậy công thức gọn gồm cả cực đại biên khi miền tham số là $[0,1]$.' ]])
    ],
    reviewNote:'Checked the likelihood on the closed interval [0,1]; all-failure data maximize at the included endpoint p=0.',
    sourceIds:['f-1805']
  },
  'f-w025-e3':{
    application:bi(['A likelihood compares parameter values for observed data, while a posterior distribution requires a prior measure and Bayes normalization.','Hàm hợp lý so sánh giá trị tham số cho dữ liệu quan sát, còn phân phối hậu nghiệm cần độ đo tiên nghiệm và chuẩn hóa Bayes.']),
    formula:bi(['For observed $x$, likelihood is $L(\\theta;x)=p_\\theta(x)$ as a function of $\\theta$; posterior density is proportional to $L(\\theta;x)\\,\\pi(\\theta)$ relative to a specified prior.','Với $x$ quan sát, likelihood là $L(\\theta;x)=p_\\theta(x)$ theo biến $\\theta$; mật độ hậu nghiệm tỷ lệ với $L(\\theta;x)\\,\\pi(\\theta)$ theo tiên nghiệm đã nêu.']),
    steps:[bi(['Fix the observed data and view the sampling probability as a function of the parameter.','Cố định dữ liệu quan sát và xem xác suất lấy mẫu như hàm của tham số.' ]),bi(['Do not assume this function integrates to one over parameter values.','Không giả sử hàm này tích phân bằng một theo tham số.' ]),bi(['To form a posterior, multiply by a prior density and divide by the marginal evidence, when finite.','Để tạo hậu nghiệm, nhân mật độ tiên nghiệm rồi chia bằng chứng biên nếu hữu hạn.' ])],
    primarySolution:[bi(['For one Bernoulli observation $x=1$, the likelihood on $p\\in[0,1]$ is $L(p)=p$.','Với một quan sát Bernoulli $x=1$, likelihood trên $p\\in[0,1]$ là $L(p)=p$.' ]),bi(['Its integral with respect to ordinary length is $\\int_0^1p\\,dp=1/2$, not $1$.','Tích phân theo độ dài thông thường là $\\int_0^1p\\,dp=1/2$, không phải $1$.' ]),bi(['Therefore likelihood is not a probability density on parameters; a prior and normalization are required to define the posterior.','Vì vậy likelihood không phải mật độ xác suất trên tham số; cần tiên nghiệm và chuẩn hóa để định nghĩa hậu nghiệm.' ])],
    companions:[
      q(['For data $x=0$ from one Bernoulli trial, write the likelihood and integrate it over $p\\in[0,1]$.','Với dữ liệu $x=0$ từ một phép thử Bernoulli, viết likelihood và tích phân trên $p\\in[0,1]$.'],[['The likelihood is $L(p)=1-p$.','Likelihood là $L(p)=1-p$.' ],['Its integral is $\\int_0^1(1-p)\\,dp=1-1/2=1/2$.','Tích phân là $\\int_0^1(1-p)\\,dp=1-1/2=1/2$.' ],['Since it does not integrate to one as a function of $p$, it is not itself a parameter density.','Vì không tích phân bằng một theo $p$, bản thân nó không phải mật độ tham số.' ]]),
      q(['With one Bernoulli success and a uniform prior $\\pi(p)=1$ on $[0,1]$, compute the posterior density.','Với một thành công Bernoulli và tiên nghiệm đều $\\pi(p)=1$ trên $[0,1]$, tính mật độ hậu nghiệm.'],[['The unnormalized posterior is $p\\cdot1=p$.','Hậu nghiệm chưa chuẩn hóa là $p\\cdot1=p$.' ],['The normalizing constant is $\\int_0^1p\\,dp=1/2$.','Hằng số chuẩn hóa là $\\int_0^1p\\,dp=1/2$.' ],['Hence $\\pi(p\\mid x=1)=2p$ on $[0,1]$, which integrates to one.','Vậy $\\pi(p\\mid x=1)=2p$ trên $[0,1]$, có tích phân bằng một.' ]]),
      q(['Why does multiplying a likelihood by a positive constant independent of the parameter leave the MLE unchanged, and what happens to the normalized posterior if the prior is fixed?','Vì sao nhân likelihood với hằng dương không phụ thuộc tham số giữ nguyên MLE, và hậu nghiệm đã chuẩn hóa thay đổi thế nào nếu giữ nguyên tiên nghiệm?'],[['For fixed data, multiplying the likelihood by a positive constant preserves which parameter maximizes it.','Với dữ liệu cố định, nhân likelihood với hằng dương giữ nguyên tham số tối đa hóa.' ],['The unnormalized posterior is also multiplied by that constant, but its normalizing evidence is multiplied by the same amount.','Hậu nghiệm chưa chuẩn hóa cũng nhân hằng đó, nhưng bằng chứng chuẩn hóa cũng nhân cùng lượng.' ],['The factor cancels, so the normalized posterior is unchanged when the prior is fixed; changing the prior can change it.','Hệ số triệt tiêu nên hậu nghiệm chuẩn hóa không đổi khi giữ nguyên tiên nghiệm; đổi tiên nghiệm có thể làm hậu nghiệm đổi.' ]])
    ],
    reviewNote:'The Bernoulli likelihood integrals are computed against length measure; posterior claims explicitly require and normalize a prior.',
    sourceIds:['f-1805']
  },
  'f-w025-e4':{
    application:bi(['A model can fit the same observable distribution with several parameter values; MLE output is then a set, not a uniquely identified number.','Mô hình có thể khớp cùng phân phối quan sát với nhiều giá trị tham số; khi đó MLE là một tập, không phải số duy nhất được nhận diện.']),
    formula:bi(['For $X_i\\sim\\operatorname{Bernoulli}(\\theta^2)$ with $\\theta\\in[-1,1]$, $\\hat p=S/n$ and the MLE set is $\\{-\\sqrt{\\hat p},+\\sqrt{\\hat p}\\}$ when $\\hat p>0$, and $\\{0\\}$ when $\\hat p=0$.','Với $X_i\\sim\\operatorname{Bernoulli}(\\theta^2)$, $\\theta\\in[-1,1]$, $\\hat p=S/n$ và tập MLE là $\\{-\\sqrt{\\hat p},+\\sqrt{\\hat p}\\}$ khi $\\hat p>0$, còn $\\{0\\}$ khi $\\hat p=0$.']),
    steps:[bi(['Recognize that the distribution depends on $\\theta$ only through $p=\\theta^2$.','Nhận ra phân phối chỉ phụ thuộc $\\theta$ qua $p=\\theta^2$.' ]),bi(['First maximize the Bernoulli likelihood over $p\\in[0,1]$, obtaining $\\hat p=S/n$.','Trước hết tối đa hóa likelihood Bernoulli theo $p\\in[0,1]$, được $\\hat p=S/n$.' ]),bi(['Solve $\\theta^2=\\hat p$ within the stated parameter space and retain all roots.','Giải $\\theta^2=\\hat p$ trong miền tham số đã cho và giữ mọi nghiệm.' ])],
    primarySolution:[bi(['Bernoulli data identify the success probability MLE $\\hat p=S/n$.','Dữ liệu Bernoulli cho MLE xác suất thành công $\\hat p=S/n$.' ]),bi(['The parameter must satisfy $\\theta^2=\\hat p$. For $\\hat p>0$, this gives two feasible values $\\theta=\\pm\\sqrt{\\hat p}$.','Tham số phải thỏa $\\theta^2=\\hat p$. Với $\\hat p>0$, có hai giá trị khả dĩ $\\theta=\\pm\\sqrt{\\hat p}$.' ]),bi(['At $\\hat p=0$ both roots coincide at $0$. The sign is not identifiable because $\\theta$ and $-\\theta$ induce the same law.','Khi $\\hat p=0$, hai nghiệm cùng bằng $0$. Dấu không được nhận diện vì $\\theta$ và $-\\theta$ cho cùng luật.' ])],
    companions:[
      q(['If $n=20$ Bernoulli observations have $S=5$ successes under success probability $\\theta^2$, $\\theta\\in[-1,1]$, find every MLE.','Nếu $n=20$ quan sát Bernoulli có $S=5$ thành công dưới xác suất thành công $\\theta^2$, $\\theta\\in[-1,1]$, tìm mọi MLE.'],[['The fitted success probability is $\\hat p=5/20=1/4$.','Xác suất thành công khớp là $\\hat p=5/20=1/4$.' ],['Solve $\\theta^2=1/4$ to obtain $\\theta=1/2$ or $\\theta=-1/2$.','Giải $\\theta^2=1/4$ được $\\theta=1/2$ hoặc $\\theta=-1/2$.' ],['Both values give the same Bernoulli law, so both maximize likelihood.','Cả hai giá trị cho cùng luật Bernoulli nên đều tối đa hóa likelihood.' ]]),
      q(['All 12 Bernoulli observations are failures in the model $p=\\theta^2$, $\\theta\\in[-1,1]$. Find the MLE set.','Cả 12 quan sát Bernoulli đều thất bại trong mô hình $p=\\theta^2$, $\\theta\\in[-1,1]$. Tìm tập MLE.'],[['The empirical success proportion is $\\hat p=0$.','Tỷ lệ thành công mẫu là $\\hat p=0$.' ],['Maximizing requires $\\theta^2=0$.','Tối đa hóa yêu cầu $\\theta^2=0$.' ],['The only solution is $\\theta=0$, so the MLE set is $\\{0\\}$.','Nghiệm duy nhất là $\\theta=0$, nên tập MLE là $\\{0\\}$.' ]]),
      q(['Show directly why the sign of $\\theta$ cannot be identified from any sample in the model $X\\sim\\operatorname{Bernoulli}(\\theta^2)$.','Chứng minh trực tiếp vì sao không thể nhận diện dấu $\\theta$ từ bất kỳ mẫu nào trong mô hình $X\\sim\\operatorname{Bernoulli}(\\theta^2)$.'],[['For each $x\\in\\{0,1\\}$, the probability is $(\\theta^2)^x(1-\\theta^2)^{1-x}$.','Với mỗi $x\\in\\{0,1\\}$, xác suất là $(\\theta^2)^x(1-\\theta^2)^{1-x}$.' ],['Replacing $\\theta$ by $-\\theta$ leaves $\\theta^2$ and hence every observation probability unchanged.','Thay $\\theta$ bằng $-\\theta$ giữ nguyên $\\theta^2$ và do đó mọi xác suất quan sát.' ],['Products over any sample remain equal, so the two parameters induce identical sampling distributions.','Tích xác suất trên mọi mẫu vẫn bằng nhau, nên hai tham số tạo phân phối lấy mẫu giống hệt.' ]])
    ],
    reviewNote:'The parameter space is explicitly [-1,1]; all roots are retained, and the zero case has a single root.',
    sourceIds:['f-1805']
  },
  'f-w025-e5':{
    application:bi(['Changing parameter coordinates should preserve an MLE when the transformation is one-to-one; nonidentifiable many-to-one maps require keeping all maximizing preimages.','Đổi tọa độ tham số nên bảo toàn MLE khi biến đổi một-một; ánh xạ nhiều-một không nhận diện cần giữ mọi tiền ảnh cực đại.']),
    formula:bi(['For bijective $g:\\Theta\\to H$, $\\tilde L(\\eta)=L(g^{-1}(\\eta))$ and $\\arg\\max_{\\eta\\in H}\\tilde L=g(\\arg\\max_{\\theta\\in\\Theta}L)$. For noninjective $g$, maximize over preimages directly.','Với song ánh $g:\\Theta\\to H$, $\\tilde L(\\eta)=L(g^{-1}(\\eta))$ và $\\arg\\max_{\\eta\\in H}\\tilde L=g(\\arg\\max_{\\theta\\in\\Theta}L)$. Với $g$ không đơn ánh, tối đa hóa trực tiếp trên các tiền ảnh.']),
    steps:[bi(['State the original parameter space and the exact transformed space $H=g(\\Theta)$.','Nêu miền tham số gốc và miền biến đổi chính xác $H=g(\\Theta)$.' ]),bi(['For a one-to-one map, rewrite the same likelihood using its inverse; the map preserves ordering of likelihood values.','Với ánh xạ một-một, viết lại cùng likelihood qua nghịch đảo; ánh xạ bảo toàn thứ tự giá trị likelihood.' ]),bi(['For a many-to-one map, account for every original parameter that maps to a maximizing value.','Với ánh xạ nhiều-một, xét mọi tham số gốc ánh xạ đến giá trị cực đại.' ])],
    primarySolution:[bi(['If $g$ is one-to-one, every $\\eta\\in g(\\Theta)$ has a unique inverse $g^{-1}(\\eta)$.','Nếu $g$ đơn ánh, mỗi $\\eta\\in g(\\Theta)$ có nghịch đảo duy nhất $g^{-1}(\\eta)$.' ]),bi(['Thus $\\tilde L(\\eta)=L(g^{-1}(\\eta))$ takes exactly the original likelihood values under relabeling.','Vì vậy $\\tilde L(\\eta)=L(g^{-1}(\\eta))$ nhận đúng các giá trị likelihood gốc khi đổi nhãn.' ]),bi(['Its maximizers are the images under $g$ of original maximizers. If $g$ is many-to-one, an inverse is set-valued and all maximizing preimages must be retained.','Các cực đại là ảnh qua $g$ của cực đại gốc. Nếu $g$ nhiều-một, nghịch đảo có nhiều giá trị và phải giữ mọi tiền ảnh cực đại.' ])],
    companions:[
      q(['If $\\hat\\lambda=3$ maximizes likelihood for $\\lambda>0$ and $\\eta=\\log\\lambda$, find the MLE in the transformed parameterization.','Nếu $\\hat\\lambda=3$ tối đa hóa likelihood với $\\lambda>0$ và $\\eta=\\log\\lambda$, tìm MLE trong tham số hóa mới.'],[['The map $g(\\lambda)=\\log\\lambda$ is one-to-one from $(0,\\infty)$ to $\\mathbb R$.','Ánh xạ $g(\\lambda)=\\log\\lambda$ đơn ánh từ $(0,\\infty)$ lên $\\mathbb R$.' ],['Reparameterization carries the maximizer to $\\hat\\eta=g(\\hat\\lambda)$.','Tái tham số hóa chuyển cực đại thành $\\hat\\eta=g(\\hat\\lambda)$.' ],['Therefore $\\hat\\eta=\\log3$.','Vậy $\\hat\\eta=\\log3$.' ]]),
      q(['A likelihood in $\\theta\\in[-1,1]$ depends only on $\\eta=\\theta^2$ and is maximized at $\\hat\\eta=0.36$. Find the original MLE set.','Likelihood theo $\\theta\\in[-1,1]$ chỉ phụ thuộc $\\eta=\\theta^2$ và đạt cực đại tại $\\hat\\eta=0.36$. Tìm tập MLE gốc.'],[['Solve the transformed maximizing equation $\\theta^2=0.36$.','Giải phương trình cực đại biến đổi $\\theta^2=0.36$.' ],['Its feasible roots are $\\theta=0.6$ and $\\theta=-0.6$.','Các nghiệm khả dĩ là $\\theta=0.6$ và $\\theta=-0.6$.' ],['Both preimages are MLEs because the transformation is many-to-one and likelihood is a function of $\\eta$ alone.','Cả hai tiền ảnh là MLE vì biến đổi nhiều-một và likelihood chỉ là hàm của $\\eta$.' ]]),
      q(['An original likelihood has maximizers $\\theta=1$ and $\\theta=2$. Under the one-to-one transformation $\\eta=\\theta+3$, find the transformed maximizer set.','Likelihood ban đầu đạt cực đại tại $\\theta=1$ và $\\theta=2$. Dưới biến đổi một-một $\\eta=\\theta+3$, tìm tập cực đại sau biến đổi.'],[['The transformation is one-to-one, so it maps each original maximizer to exactly one new parameter value.','Biến đổi đơn ánh nên ánh xạ mỗi cực đại gốc đến đúng một giá trị tham số mới.' ],['Compute $g(1)=4$ and $g(2)=5$.','Tính $g(1)=4$ và $g(2)=5$.' ],['The transformed maximizer set is $\\{4,5\\}$, the image of the original set.','Tập cực đại biến đổi là $\\{4,5\\}$, ảnh của tập gốc.' ]])
    ],
    reviewNote:'The one-to-one theorem is restricted to g(Θ); the noninjective examples retain all parameter preimages.',
    sourceIds:['f-1805']
  },
  'f-w026-e1':{
    application:bi(['For a Bernoulli sample, the success count retains all likelihood information about the success probability even though the ordered sample has more entries.','Với mẫu Bernoulli, số lần thành công giữ toàn bộ thông tin likelihood về xác suất thành công dù mẫu có thứ tự nhiều phần tử hơn.']),
    formula:bi(['For IID $X_i\\sim\\operatorname{Bernoulli}(p)$, $f_p(x)=p^{S(x)}(1-p)^{n-S(x)}\\,\\mathbf1\\{x\\in\\{0,1\\}^n\\}$, where $S=\\sum_i x_i$; factorization makes $S$ sufficient.','Với $X_i\\sim\\operatorname{Bernoulli}(p)$ IID, $f_p(x)=p^{S(x)}(1-p)^{n-S(x)}\\,\\mathbf1\\{x\\in\\{0,1\\}^n\\}$, trong đó $S=\\sum_i x_i$; phân tích nhân tử cho thấy $S$ đủ.']),
    steps:[bi(['Write the joint PMF as a product over observations.','Viết PMF chung thành tích theo từng quan sát.' ]),bi(['Collect the success and failure factors into powers depending on $S$.','Gom các thừa số thành công và thất bại thành lũy thừa phụ thuộc $S$.' ]),bi(['Separate the parameter-dependent factor from the support indicator; apply the factorization criterion.','Tách nhân tử phụ thuộc tham số khỏi chỉ báo miền giá trị; áp dụng tiêu chuẩn phân tích nhân tử.' ])],
    primarySolution:[bi(['Independence gives $f_p(x_1,\\ldots,x_n)=\\prod_i p^{x_i}(1-p)^{1-x_i}$.','Độc lập cho $f_p(x_1,\\ldots,x_n)=\\prod_i p^{x_i}(1-p)^{1-x_i}$.' ]),bi(['Collect exponents: $\\prod_i p^{x_i}(1-p)^{1-x_i}=p^{\\sum_i x_i}(1-p)^{n-\\sum_i x_i}=p^S(1-p)^{n-S}$.','Gom số mũ: $\\prod_i p^{x_i}(1-p)^{1-x_i}=p^{\\sum_i x_i}(1-p)^{n-\\sum_i x_i}=p^S(1-p)^{n-S}$.' ]),bi(['The support indicator depends only on whether the observed vector is binary, not on $p$; the parameter enters the data through $S$ alone, so the factorization criterion makes $S$ sufficient.','Chỉ báo miền giá trị chỉ phụ thuộc vectơ quan sát có nhị phân hay không, không phụ thuộc $p$; tham số đi vào dữ liệu chỉ qua $S$, nên tiêu chuẩn phân tích nhân tử cho $S$ là đủ.' ])],
    companions:[
      q(['For four IID Bernoulli observations $x=(1,0,1,1)$, factor the joint PMF and identify the statistic carrying the parameter dependence.','Với bốn quan sát Bernoulli IID $x=(1,0,1,1)$, phân tích PMF chung và nêu thống kê chứa phụ thuộc tham số.'],[['There are $S=3$ successes and $1$ failure.','Có $S=3$ thành công và $1$ thất bại.' ],['The joint probability is $p^3(1-p)^1$.','Xác suất chung là $p^3(1-p)^1$.' ],['In a general sample vector the same factor depends on the vector only through $S$, establishing sufficiency by factorization.','Với vectơ mẫu tổng quát, nhân tử tương tự chỉ phụ thuộc vectơ qua $S$, chứng minh tính đủ theo phân tích nhân tử.' ]]),
      q(['For IID Bernoulli data, show the sample mean and success count contain the same information about $p$.','Với dữ liệu Bernoulli IID, chứng minh trung bình mẫu và số thành công chứa cùng thông tin về $p$.'],[['Each observation is $0$ or $1$, so $\\bar X=S/n$.','Mỗi quan sát là $0$ hoặc $1$, nên $\\bar X=S/n$.' ],['For fixed known sample size $n$, this is a one-to-one transformation between $S$ and $\\bar X$.','Với cỡ mẫu $n$ cố định đã biết, đây là biến đổi một-một giữa $S$ và $\\bar X$.' ],['Thus either statistic determines the other and yields the same likelihood factorization.','Vì vậy mỗi thống kê xác định thống kê kia và cho cùng phân tích likelihood.' ]]),
      q(['Why would the factorization argument need modification if observations came from a model with parameter-dependent support?','Vì sao lập luận phân tích nhân tử cần sửa nếu quan sát đến từ mô hình có miền hỗ trợ phụ thuộc tham số?'],[['The joint density contains both its algebraic expression and an indicator of its support.','Mật độ chung gồm biểu thức đại số và chỉ báo miền hỗ trợ.' ],['If that indicator depends on $p$, it cannot automatically be placed in a parameter-free factor $h(x)$.','Nếu chỉ báo phụ thuộc $p$, không thể tự động đặt nó vào nhân tử $h(x)$ không phụ thuộc tham số.' ],['One must inspect the full factorization or use the conditional-distribution definition of sufficiency.','Cần kiểm tra phân tích đầy đủ hoặc dùng định nghĩa đủ qua phân phối có điều kiện.' ]])
    ],
    reviewNote:'Expanded the full joint PMF with its binary support indicator; the support is parameter-free here, so the factorization criterion applies.',
    sourceIds:['f-1805']
  },
  'f-w026-e2':{
    application:bi(['Conditioning an unbiased noisy estimator on a sufficient statistic removes irrelevant sample-order noise and cannot increase variance.','Điều kiện hóa ước lượng không chệch nhiễu theo thống kê đủ loại bỏ nhiễu thứ tự mẫu không cần thiết và không làm tăng phương sai.']),
    formula:bi(['For two IID $\\operatorname{Bernoulli}(p)$ observations and $S=X_1+X_2$, $E[X_1\\mid S]=S/2$; its variance is $\\operatorname{Var}(S/2)=p(1-p)/2$.','Với hai quan sát $\\operatorname{Bernoulli}(p)$ IID và $S=X_1+X_2$, $E[X_1\\mid S]=S/2$; phương sai là $\\operatorname{Var}(S/2)=p(1-p)/2$.']),
    steps:[bi(['When $S=0$ or $S=2$, symmetry forces $X_1$ to equal that value.','Khi $S=0$ hoặc $S=2$, tính đối xứng buộc $X_1$ bằng giá trị đó.' ]),bi(['When $S=1$, the two configurations $(1,0)$ and $(0,1)$ are equiprobable conditionally, so the mean is $1/2$.','Khi $S=1$, hai cấu hình $(1,0)$ và $(0,1)$ đồng xác suất có điều kiện, nên trung bình là $1/2$.' ]),bi(['Use the binomial variance of $S$ and scale by $(1/2)^2$ to compute the Rao–Blackwell estimator variance.','Dùng phương sai nhị thức của $S$ và nhân $(1/2)^2$ để tính phương sai ước lượng Rao–Blackwell.' ])],
    primarySolution:[bi(['Conditionally on $S=0$, $X_1=0$; on $S=2$, $X_1=1$.','Có điều kiện theo $S=0$, $X_1=0$; theo $S=2$, $X_1=1$.' ]),bi(['Given $S=1$, configurations $(1,0)$ and $(0,1)$ have equal conditional probability by exchangeability, so $E[X_1\\mid S=1]=1/2$. Thus $E[X_1\\mid S]=S/2$.','Với $S=1$, cấu hình $(1,0)$ và $(0,1)$ có xác suất điều kiện bằng nhau do hoán đổi, nên $E[X_1\\mid S=1]=1/2$. Vậy $E[X_1\\mid S]=S/2$.' ]),bi(['Since $S\\sim\\operatorname{Binomial}(2,p)$, $\\operatorname{Var}(S/2)=2p(1-p)/4=p(1-p)/2$.','Vì $S\\sim\\operatorname{Binomial}(2,p)$, $\\operatorname{Var}(S/2)=2p(1-p)/4=p(1-p)/2$.' ])],
    companions:[
      q(['For two IID Bernoulli trials, list $E[X_1\\mid S=k]$ for each possible $k$.','Với hai phép thử Bernoulli IID, liệt kê $E[X_1\\mid S=k]$ cho mỗi $k$ có thể.'],[['If $k=0$, both trials are failures, so the conditional expectation is $0$.','Nếu $k=0$, cả hai lần đều thất bại, nên kỳ vọng có điều kiện bằng $0$.' ],['If $k=1$, symmetry gives probability $1/2$ that the success is in position 1, so expectation $1/2$.','Nếu $k=1$, đối xứng cho xác suất $1/2$ thành công ở vị trí 1, nên kỳ vọng $1/2$.' ],['If $k=2$, both are successes, so expectation $1$. The three values equal $k/2$.','Nếu $k=2$, cả hai đều thành công, nên kỳ vọng $1$. Ba giá trị bằng $k/2$.' ]]),
      q(['Compare $\\operatorname{Var}(X_1)$ and $\\operatorname{Var}(E[X_1\\mid S])$ at $p=1/4$.','So sánh $\\operatorname{Var}(X_1)$ và $\\operatorname{Var}(E[X_1\\mid S])$ tại $p=1/4$.'],[['The raw estimator variance is $p(1-p)=\\frac14\\frac34=3/16$.','Phương sai ước lượng thô là $p(1-p)=\\frac14\\frac34=3/16$.' ],['The conditioned estimator variance is half that, $p(1-p)/2=3/32$.','Phương sai ước lượng có điều kiện bằng một nửa, $p(1-p)/2=3/32$.' ],['The variance reduction is $3/16-3/32=3/32$, consistent with the law of total variance.','Mức giảm phương sai là $3/16-3/32=3/32$, phù hợp với luật phương sai toàn phần.' ]]),
      q(['For $p=0.6$, calculate the probability of $S=1$ and the conditional chance that $X_1=1$ given $S=1$.','Với $p=0.6$, tính xác suất $S=1$ và xác suất có điều kiện $X_1=1$ khi biết $S=1$.'],[['Exactly one success occurs in two ways, so $P(S=1)=2p(1-p)=2(0.6)(0.4)=0.48$.','Đúng một thành công xảy ra theo hai cách, nên $P(S=1)=2p(1-p)=2(0.6)(0.4)=0.48$.' ],['The two configurations $(1,0)$ and $(0,1)$ each have probability $p(1-p)=0.24$.','Hai cấu hình $(1,0)$ và $(0,1)$ mỗi cấu hình có xác suất $p(1-p)=0.24$.' ],['Their conditional probabilities given $S=1$ are each $0.24/0.48=1/2$, so the conditional chance is $1/2$.','Xác suất có điều kiện của mỗi cấu hình khi biết $S=1$ là $0.24/0.48=1/2$, nên xác suất cần tìm là $1/2$.' ]])
    ],
    reviewNote:'Conditioning uses exchangeability of two IID Bernoulli trials; the variance computation assumes p∈[0,1].',
    sourceIds:['f-1805']
  },
  'f-w026-e3':{
    application:bi(['In a hierarchical data analysis, total variability splits into average within-group variability and between-group variability of conditional means.','Trong phân tích dữ liệu phân cấp, biến thiên tổng tách thành biến thiên trung bình trong nhóm và biến thiên giữa các trung bình có điều kiện.']),
    formula:bi(['For finite-second-moment $X$ and finite-valued $T$, $\\operatorname{Var}(X)=E[\\operatorname{Var}(X\\mid T)]+\\operatorname{Var}(E[X\\mid T])$.','Với $X$ có moment bậc hai hữu hạn và $T$ hữu hạn giá trị, $\\operatorname{Var}(X)=E[\\operatorname{Var}(X\\mid T)]+\\operatorname{Var}(E[X\\mid T])$.']),
    steps:[bi(['Write $E[X^2\\mid T]=\\operatorname{Var}(X\\mid T)+(E[X\\mid T])^2$.','Viết $E[X^2\\mid T]=\\operatorname{Var}(X\\mid T)+(E[X\\mid T])^2$.' ]),bi(['Take expectations and use $E[E[X\\mid T]]=E[X]$.','Lấy kỳ vọng và dùng $E[E[X\\mid T]]=E[X]$.' ]),bi(['Subtract $(E X)^2$ and recognize the variance of the conditional mean.','Trừ $(E X)^2$ rồi nhận ra phương sai của kỳ vọng có điều kiện.' ])],
    primarySolution:[bi(['By the conditional variance definition, $E[X^2\\mid T]=\\operatorname{Var}(X\\mid T)+(E[X\\mid T])^2$.','Theo định nghĩa phương sai có điều kiện, $E[X^2\\mid T]=\\operatorname{Var}(X\\mid T)+(E[X\\mid T])^2$.' ]),bi(['Take expectations: $E[X^2]=E[\\operatorname{Var}(X\\mid T)]+E[(E[X\\mid T])^2]$.','Lấy kỳ vọng: $E[X^2]=E[\\operatorname{Var}(X\\mid T)]+E[(E[X\\mid T])^2]$.' ]),bi(['Subtract $(EX)^2=(E[E(X\\mid T)])^2$ from both sides to obtain the claimed decomposition.','Trừ $(EX)^2=(E[E(X\\mid T)])^2$ hai vế để được phân rã cần chứng minh.' ])],
    companions:[
      q(['A two-group model has $P(T=1)=1/4$, $P(T=2)=3/4$, conditional means $0$ and $4$, and within-group variances $1$ and $1$. Find total variance.','Mô hình hai nhóm có $P(T=1)=1/4$, $P(T=2)=3/4$, kỳ vọng có điều kiện $0$ và $4$, phương sai trong nhóm lần lượt là $1$ và $1$. Tính phương sai tổng.'],[['The expected conditional variance is $(1/4)(1)+(3/4)(1)=1$.','Kỳ vọng phương sai có điều kiện là $(1/4)(1)+(3/4)(1)=1$.' ],['The overall mean of the conditional means is $(1/4)(0)+(3/4)(4)=3$.','Trung bình chung của các kỳ vọng có điều kiện là $(1/4)(0)+(3/4)(4)=3$.' ],['Between-group variance is $(1/4)(0-3)^2+(3/4)(4-3)^2=3$; total variance is $1+3=4$.','Phương sai giữa nhóm là $(1/4)(0-3)^2+(3/4)(4-3)^2=3$; phương sai tổng là $1+3=4$.' ]]),
      q(['If $E[X\\mid T]$ is constant almost surely, what does the variance decomposition say about $\\operatorname{Var}(X)$?','Nếu $E[X\\mid T]$ là hằng số hầu chắc chắn, phân rã phương sai nói gì về $\\operatorname{Var}(X)$?'],[['A constant random variable has variance zero, so $\\operatorname{Var}(E[X\\mid T])=0$.','Biến ngẫu nhiên hằng có phương sai không, nên $\\operatorname{Var}(E[X\\mid T])=0$.' ],['Substitute into total variance: $\\operatorname{Var}(X)=E[\\operatorname{Var}(X\\mid T)]$.','Thay vào phương sai toàn phần: $\\operatorname{Var}(X)=E[\\operatorname{Var}(X\\mid T)]$.' ],['All variability is then within the conditioning groups, with no between-group mean variation.','Khi đó toàn bộ biến thiên nằm trong các nhóm điều kiện, không có biến thiên trung bình giữa nhóm.' ]]),
      q(['For $X$ Bernoulli($p$) and $T=X$, verify both terms of total variance.','Với $X$ Bernoulli($p$) và $T=X$, kiểm tra hai số hạng của phương sai toàn phần.'],[['Given $T=X$, $X$ is known, so $\\operatorname{Var}(X\\mid T)=0$.','Khi biết $T=X$, giá trị $X$ đã biết, nên $\\operatorname{Var}(X\\mid T)=0$.' ],['The conditional mean $E[X\\mid T]=T=X$, whose variance is $p(1-p)$.','Kỳ vọng có điều kiện $E[X\\mid T]=T=X$, có phương sai $p(1-p)$.' ],['The decomposition gives $0+p(1-p)=\\operatorname{Var}(X)$, as required.','Phân rã cho $0+p(1-p)=\\operatorname{Var}(X)$, đúng như cần.' ]])
    ],
    reviewNote:'Derived total variance by conditioning the second moment; the examples respect the finite-second-moment hypothesis.',
    sourceIds:['f-1805']
  },
  'f-w026-e4':{
    title:bi(['Completeness for one Bernoulli observation','Tính đầy đủ với một quan sát Bernoulli']),
    application:bi(['Completeness asks whether a statistic admits any nonzero zero-mean function uniformly over the entire parameter family; checking one model is not a universal theorem.','Tính đầy đủ hỏi thống kê có hàm khác không nào có kỳ vọng bằng không đồng đều trên toàn họ tham số hay không; kiểm tra một mô hình không phải định lý phổ quát.']),
    formula:bi(['For $X\\sim\\operatorname{Bernoulli}(p)$ with $p\\in(0,1)$, completeness means $E_p[g(X)]=p g(1)+(1-p)g(0)=0$ for all $p$ implies $g(0)=g(1)=0$.','Với $X\\sim\\operatorname{Bernoulli}(p)$, $p\\in(0,1)$, tính đầy đủ nghĩa là $E_p[g(X)]=p g(1)+(1-p)g(0)=0$ với mọi $p$ suy ra $g(0)=g(1)=0$.']),
    steps:[bi(['Write the expectation of $g(X)$ as a function of $p$ using the two possible outcomes.','Viết kỳ vọng $g(X)$ thành hàm của $p$ qua hai kết quả có thể.' ]),bi(['Impose that this affine function is zero for every $p$ in the open interval.','Đặt điều kiện hàm affine này bằng không với mọi $p$ trong khoảng mở.' ]),bi(['A function vanishing on an interval has both coefficients zero, forcing both values of $g$ to vanish.','Hàm triệt tiêu trên cả khoảng có hai hệ số bằng không, buộc hai giá trị của $g$ bằng không.' ])],
    primarySolution:[bi(['The only outcomes are $0$ and $1$, so $E_p[g(X)]=p g(1)+(1-p)g(0)$.','Hai kết quả duy nhất là $0$ và $1$, nên $E_p[g(X)]=p g(1)+(1-p)g(0)$.' ]),bi(['Rewrite this as $g(0)+p(g(1)-g(0))$. If it is zero for all $p\\in(0,1)$, its slope and intercept must both be zero.','Viết lại thành $g(0)+p(g(1)-g(0))$. Nếu bằng không với mọi $p\\in(0,1)$, hệ số góc và hệ số tự do đều bằng không.' ]),bi(['Thus $g(0)=0$ and $g(1)-g(0)=0$, so $g(1)=0$; this proves completeness for this specific statistic and family.','Vậy $g(0)=0$ và $g(1)-g(0)=0$, nên $g(1)=0$; điều này chứng minh tính đầy đủ cho thống kê và họ cụ thể này.' ])],
    companions:[
      q(['For a Bernoulli($p$) observation, suppose $E_p[g(X)]=0$ for every $p\\in(0,1)$. Use limits as $p$ approaches the endpoints to identify $g(0)$ and $g(1)$.','Với một quan sát Bernoulli($p$), giả sử $E_p[g(X)]=0$ với mọi $p\\in(0,1)$. Dùng giới hạn khi $p$ tiến đến hai đầu để tìm $g(0)$ và $g(1)$.'],[['The equation is $p g(1)+(1-p)g(0)=0$ for each interior $p$.','Phương trình là $p g(1)+(1-p)g(0)=0$ với mọi $p$ trong khoảng.' ],['Let $p\\downarrow0$; continuity of this affine expression gives $g(0)=0$.','Cho $p\\downarrow0$; tính liên tục của biểu thức affine cho $g(0)=0$.' ],['Let $p\\uparrow1$ to get $g(1)=0$; thus only the zero function has zero expectation throughout the family.','Cho $p\\uparrow1$ được $g(1)=0$; vậy chỉ hàm không có kỳ vọng không trên toàn họ.' ]]),
      q(['Why is checking $E_{1/2}[g(X)]=0$ alone insufficient to prove completeness of the Bernoulli family?','Vì sao chỉ kiểm $E_{1/2}[g(X)]=0$ không đủ chứng minh tính đầy đủ của họ Bernoulli?'],[['At the single value $p=1/2$, the condition is $[g(0)+g(1)]/2=0$.','Tại riêng $p=1/2$, điều kiện là $[g(0)+g(1)]/2=0$.' ],['For example, $g(0)=1$ and $g(1)=-1$ satisfy it without being the zero function.','Chẳng hạn $g(0)=1$ và $g(1)=-1$ thỏa điều kiện nhưng không phải hàm không.' ],['Completeness requires zero expectation for every parameter value in the family, not one selected parameter.','Tính đầy đủ yêu cầu kỳ vọng bằng không với mọi giá trị tham số trong họ, không phải một tham số chọn trước.' ]]),
      q(['A statistic has a sufficient factorization in a model. Does this calculation alone prove the statistic complete? Explain logically.','Một thống kê có phân tích nhân tử đủ trong mô hình. Riêng phép tính này có chứng minh thống kê đầy đủ không? Giải thích logic.'],[['The factorization criterion establishes sufficiency by separating parameter and data dependence.','Tiêu chuẩn phân tích nhân tử chứng minh tính đủ bằng cách tách phụ thuộc tham số và dữ liệu.' ],['Completeness is a different universal expectation condition on functions of the statistic.','Tính đầy đủ là điều kiện kỳ vọng phổ quát khác trên các hàm của thống kê.' ],['Therefore sufficiency alone does not prove completeness; a separate model-specific argument or counterexample is needed.','Do đó tính đủ riêng không chứng minh tính đầy đủ; cần lập luận riêng theo mô hình hoặc một phản ví dụ.' ]])
    ],
    reviewNote:'Corrected source heading: the primary proves completeness only for n=1 Bernoulli(p), p∈(0,1), while explicitly distinguishing that fact from the universal sufficiency implication.',
    sourceIds:['f-1805']
  },
  'f-w026-e5':{
    application:bi(['When a statistic partitions a finite outcome space, conditioning an estimator averages within cells; cell probabilities come from the sampling law and need not be proportional to cell sizes.','Khi thống kê phân hoạch không gian kết quả hữu hạn, điều kiện hóa ước lượng lấy trung bình trong từng ô; xác suất ô đến từ luật lấy mẫu và không nhất thiết tỷ lệ với kích thước ô.']),
    formula:bi(['For finite outcomes and cells with $P(C_j)>0$, $E[\\delta]=\\sum_j E[\\delta\\mid C_j]P(C_j)$ and the Rao–Blackwell estimator is $E[\\delta\\mid T]$, constant on each cell $C_j=\\{T=t_j\\}$.','Với kết quả hữu hạn và ô có $P(C_j)>0$, $E[\\delta]=\\sum_j E[\\delta\\mid C_j]P(C_j)$ và ước lượng Rao–Blackwell là $E[\\delta\\mid T]$, hằng trên mỗi ô $C_j=\\{T=t_j\\}$.']),
    steps:[bi(['Find each conditional cell mean to define $E[\\delta\\mid T]$.','Tìm trung bình có điều kiện trong từng ô để xác định $E[\\delta\\mid T]$.' ]),bi(['Weight the cell means by their model probabilities, not just by their cardinalities.','Cân các trung bình ô bằng xác suất theo mô hình, không chỉ theo số phần tử.' ]),bi(['To verify unbiasedness, compare the resulting expectation with the target under the stated model.','Để kiểm tra không chệch, so sánh kỳ vọng thu được với mục tiêu trong mô hình đã nêu.' ])],
    primarySolution:[bi(['Let $C_1,C_2$ have sizes $2,3$ in a five-outcome uniform space. Then $P(C_1)=2/5$ and $P(C_2)=3/5$.','Cho $C_1,C_2$ có kích thước $2,3$ trong không gian đều năm kết quả. Khi đó $P(C_1)=2/5$ và $P(C_2)=3/5$.' ]),bi(['The conditional estimator takes value $1$ on $C_1$ and $2$ on $C_2$.','Ước lượng có điều kiện nhận giá trị $1$ trên $C_1$ và $2$ trên $C_2$.' ]),bi(['Its expectation is $(1)(2/5)+(2)(3/5)=8/5$. To verify unbiasedness one must know the target and confirm the sampling probabilities used here.','Kỳ vọng là $(1)(2/5)+(2)(3/5)=8/5$. Muốn xác nhận không chệch cần biết mục tiêu và kiểm tra xác suất lấy mẫu đã dùng.' ])],
    companions:[
      q(['A uniform five-outcome space is partitioned into cells of sizes 1 and 4. A conditional estimator equals 3 on the first cell and 1 on the second. Find its expectation.','Không gian đều năm kết quả được chia thành ô kích thước 1 và 4. Ước lượng có điều kiện bằng 3 trên ô đầu và 1 trên ô sau. Tính kỳ vọng.'],[['Uniformity gives cell probabilities $1/5$ and $4/5$.','Tính đều cho xác suất ô $1/5$ và $4/5$.' ],['Weight the values: $3(1/5)+1(4/5)$.','Cân các giá trị: $3(1/5)+1(4/5)$.' ],['The expectation is $3/5+4/5=7/5$.','Kỳ vọng là $3/5+4/5=7/5$.' ]]),
      q(['Two partition cells have sizes 2 and 3, but their probabilities are 0.8 and 0.2. Conditional estimator values are 1 and 2. Find its expectation and compare with size weighting.','Hai ô phân hoạch có kích thước 2 và 3 nhưng xác suất lần lượt là 0.8 và 0.2. Giá trị ước lượng có điều kiện là 1 và 2. Tính kỳ vọng và so với cân theo kích thước.'],[['Use the model probabilities: $E\\delta=1(0.8)+2(0.2)$.','Dùng xác suất mô hình: $E\\delta=1(0.8)+2(0.2)$.' ],['This equals $1.2$.','Kết quả bằng $1.2$.' ],['Cardinality weighting would give $1(2/5)+2(3/5)=1.6$, which is wrong here because the distribution is not uniform.','Cân theo số phần tử cho $1(2/5)+2(3/5)=1.6$, sai ở đây vì phân phối không đều.' ]]),
      q(['An estimator $\\delta$ is unbiased for parameter $\\theta$ and $T$ is sufficient. What does Rao–Blackwellization preserve, and which inequality can it provide?','Ước lượng $\\delta$ không chệch cho tham số $\\theta$ và $T$ đủ. Rao–Blackwell hóa bảo toàn điều gì và cho bất đẳng thức nào?'],[['By iterated expectation, $E[E(\\delta\\mid T)]=E\\delta=\\theta$, so it remains unbiased.','Theo kỳ vọng lặp, $E[E(\\delta\\mid T)]=E\\delta=\\theta$, nên vẫn không chệch.' ],['The conditional variance identity gives $\\operatorname{Var}(\\delta)=E[\\operatorname{Var}(\\delta\\mid T)]+\\operatorname{Var}(E[\\delta\\mid T])$.','Đồng nhất thức phương sai có điều kiện cho $\\operatorname{Var}(\\delta)=E[\\operatorname{Var}(\\delta\\mid T)]+\\operatorname{Var}(E[\\delta\\mid T])$.' ],['Thus $\\operatorname{Var}(E[\\delta\\mid T])\\le\\operatorname{Var}(\\delta)$; sufficiency makes the conditional estimator usable without dependence on the unknown parameter.','Vì vậy $\\operatorname{Var}(E[\\delta\\mid T])\\le\\operatorname{Var}(\\delta)$; tính đủ giúp dùng ước lượng có điều kiện mà không phụ thuộc tham số chưa biết.' ]])
    ],
    reviewNote:'Used the supplied uniform five-outcome law for the 2/5 and 3/5 weights; the transfer explicitly shows why cell sizes alone fail without uniformity.',
    sourceIds:['f-1805']
  },
};
export default reviewed;
